(window.NTDATA=window.NTDATA||{});(NTDATA.rbo=NTDATA.rbo||{})["1kgs"]={"1":{"1":"Царь Давид был уже глубоким старцем. Как его ни кутали, он все не мог согреться.","2":"И приближенные посоветовали ему: «Пусть поищут для господина нашего, царя, невинную девушку, которая будет прислуживать господину нашему, царю, и ухаживать за ним. Будет она лежать в твоих объятиях, господин наш, царь, – и ты согреешься…»","3":"По всему Израилю искали самую красивую девушку; ей оказалась Авишаг шунамитянка. Ее привели к царю.","4":"Она была несказанно красива. Она стала ухаживать за царем и прислуживать ему, но царь не познал ее.","5":"Адония, сын Хаггит, зазнался – он думал, что станет царем. Он завел себе колесницы, конницу; пятьдесят телохранителей сопровождали его.","6":"Отец никогда его не одергивал, не спрашивал: «Зачем это тебе?» Адония был очень хорош собой, по старшинству он следовал за Авессаломом.","7":"Его советчиками были Иоав, сын Церуи, и священник Авиафар; они поддерживали Адонию.","8":"Но священник Цадок, и Беная, сын Иехояды, и пророк Нафан, и Шими, и Реи, и дружина Давидова не были на стороне Адонии.","9":"Адония устроил пиршественное жертвоприношение у камня Зохелет, что близ источника Рогель. Он зарезал баранов, откормленных быков и созвал на пир всех своих братьев, царских сыновей, а также царских приближенных со всей Иудеи.","10":"А пророка Нафана, и Бенаю, и дружину, и своего брата Соломона не позвал.","11":"Тогда пророк Нафан сказал Вирсавии, матери Соломона: «Слышала? Адония, сын Хаггит, уже стал царем! А господин наш, Давид, ничего не знает.","12":"Мой тебе совет: ступай, спасай свою жизнь и жизнь своего сына Соломона!","13":"Иди к царю Давиду и скажи ему: „Господин мой, царь, ты поклялся мне, рабе твоей, что мой сын Соломон будет царем после тебя и воссядет на твой престол. Почему же царем стал Адония?\"","14":"Не успеешь ты это сказать, как и я подойду, чтобы подтвердить правоту твоих слов».","15":"Вирсавия вошла в царские покои. Царь Давид был уже очень стар, и Авишаг шунамитянка прислуживала ему.","16":"Вирсавия стала на колени и простерлась ниц перед царем. Царь спросил: «Что тебе?» –","17":"«Господин мой! – ответила она. – Ты клялся мне, рабе твоей, Господом, Богом твоим, что мой сын Соломон будет царем после тебя, что он воссядет на твой престол!","18":"Но вот царем уже сделался Адония – а ты, господин мой, царь, ничего и не знаешь!","19":"Он устроил пиршественное жертвоприношение – зарезал много откормленных быков и баранов, созвал на пир всех царских сыновей, и священника Авиафара, и военачальника Иоава, а Соломона, раба твоего, не позвал.","20":"Господин мой, царь! Взоры всех в Израиле обращены на тебя! Все ждут твоего решения: кто сменит тебя, господин мой, царь, на престоле?","21":"О господин мой, царь! Как только ты упокоишься с праотцами, меня и моего сына Соломона объявят преступниками!»","22":"Не успела она это сказать, как вошел пророк Нафан.","23":"«К тебе пророк Нафан!» – доложили царю. Представ перед царем, Нафан пал на колени, простерся ниц перед ним,","24":"и сказал: «Господин мой, царь! Ты, должно быть, сказал, что Адония станет царем после тебя и воссядет на твой престол.","25":"Сегодня он пошел и устроил пиршественное жертвоприношение, велел зарезать много откормленных быков и баранов, созвал всех сыновей царских, и военачальников, и священника Авиафара, и сейчас они все вместе с ним пируют и кричат: „Да здравствует царь Адония!\"","26":"А меня, твоего раба, и священника Цадока, и Бенаю, сына Иехояды, и раба твоего Соломона он не позвал.","27":"Правда ли, что такова воля моего господина, царя? Ты ведь так и не объявил нам, рабам твоим, кто сменит тебя, господин мой, царь, на престоле».","28":"«Позовите ко мне Вирсавию», – сказал царь Давид. Она подошла и стала перед царем.","29":"Царь сказал: «Клянусь Господом, Избавителем моим во всех моих бедах!","30":"Я поклялся тебе Господом, Богом Израиля, что твой сын Соломон будет царем после меня и воссядет на мой престол, и сегодня я это исполню».","31":"Вирсавия пала на колени, простерлась ниц перед царем и сказала: «Да будет господин мой, царь Давид, жив вовеки!»","32":"Царь Давид повелел: «Позовите ко мне священника Цадока, пророка Нафана и Бенаю, сына Иехояды!» Они предстали перед царем,","33":"и царь повелел: «Соберите приближенных вашего царя. Посадите моего сына Соломона на моего мула и спускайтесь все вместе к Гихону,","34":"а там пусть священник Цадок и пророк Нафан помажут его в цари Израиля. Протрубите в рог и провозгласите: „Да здравствует царь Соломон!\"","35":"Потом поднимайтесь вместе с ним в город, и пусть он воссядет на мой престол. Он будет царствовать после меня. Я завещаю ему быть правителем Израиля и Иудеи».","36":"«Да будет так!» – ответил царю Беная, сын Иехояды. «Да будет на то, господин мой, царь, воля Господа, Бога твоего!","37":"Как был Господь с моим господином, царем, так да будет Господь и с Соломоном! И да вознесет Господь его престол еще выше, чем престол моего господина, царя Давида!»","38":"И пошли священник Цадок, пророк Нафан и Беная, сын Иехояды, с керетянами и пелетянами, посадили Соломона на царского мула и отвели к Тихону.","39":"Священник Цадок взял рог с оливковым маслом из Шатра и помазал Соломона в цари. Протрубили в рог, и все провозгласили: «Да здравствует царь Соломон!»","40":"Потом все двинулись обратно, во главе с Соломоном. Народ играл на флейтах, радовался и ликовал, земля дрожала от криков.","41":"Эти звуки донеслись до Адонии и его гостей – а они как раз кончали пировать. Услышал Иоав звук рога и спросил: «Отчего такой шум в городе?»","42":"Едва он это промолвил, как появился Ионафан, сын священника Авиафара. «Иди сюда! – сказал ему Адония. – Ты славный человек, верно, и новости у тебя хорошие!»","43":"Ионафан ответил Адонии: «Господин наш, царь Давид, передал царство Соломону!","44":"Царь послал к нему священника Цадока, пророка Нафана и Бенаю, сына Иехояды, с керетянами и пелетянами. Они посадили Соломона на царского мула,","45":"а потом у Тихона священник Цадок и пророк Нафан помазали Соломона на царство. Вернулись они оттуда и торжествуют, весь город бурлит – вот этот шум вы и слышите.","46":"Соломон уже сел на царский престол!","47":"Царские приближенные уже приходили поздравить господина нашего, царя Давида, и сказали ему: „Бог твой да одарит Соломона славою еще большей, чем твоя слава, и да вознесет его престол еще выше, чем твой престол!\" Поклонился царь, привстав на постели,","48":"и сказал: „Благословен Господь, Бог Израиля, который сегодня дал мне увидеть моего преемника на престоле моем!\"»","49":"Ужас охватил всех собравшихся у Адонии, они вскочили и разбежались кто куда.","50":"Сам Адония, боясь Соломона, побежал к жертвеннику и схватился за рога жертвенника.","51":"Соломону доложили: «Адония боится царя Соломона. Он схватился за рога жертвенника и говорит: „Пусть сперва царь Соломон поклянется мне, что не казнит меня, раба своего!\"»","52":"Соломон ответил: «Если будет вести себя как надо, то ни один волос не упадет с его головы. А будет замечен в чем-то дурном – умрет».","53":"Царь Соломон послал за Адонией, и его увели от жертвенника. Адония пришел и поклонился царю Соломону. «Ступай к себе домой», – велел ему Соломон."},"2":{"1":"Пришло Давиду время умирать, и вот что завещал он своему сыну Соломону:","2":"«Я ухожу в путь, который всем предстоит, а ты будь тверд, будь мужчиной.","3":"Соблюдай все, что велел соблюдать Господь, твой Бог; иди путем, который Он заповедал. Исполняй Его законы, повеления, постановления и предписания, как написано в Законе Моисея – и тогда тебе будет удаваться все, что ты задумаешь, все, за что бы ты ни взялся.","4":"Тогда Господь исполнит обещание, которое Он мне дал. А Он сказал мне так: „Если потомки твои будут верно следовать по пути, что Я заповедал им, если будут служить Мне верой и правдой, всем сердцем и всей душой, то они всегда будут на престоле Израиля\".","5":"…Ты сам знаешь, как повел себя со мной Иоав, сын Церуи, как поступил он с двумя военачальниками израильскими: Авнером, сыном Нера, и Амасой, сыном Иетера, – как он убил их. Во время мира он пролил кровь, словно на войне. Кровью запятнан пояс у него на бедрах, кровью запятнана обувь у него на ногах!","6":"Но ты мудр, и ты не дашь его сединам мирно сойти в Шеол.","7":"…Потомкам Барзиллая из Галаада воздай добром за добро, пусть они будут допущены к твоему столу, ведь их род пришел мне на помощь, когда я бежал от твоего брата Авессалома.","8":"…А еще среди людей, что тебя окружают, есть Шими, сын Геры , вениамитянин из Бахурима. Он проклял меня страшным проклятьем, когда я уходил в Маханаим. После, когда он вышел мне навстречу у Иордана, я поклялся Господом, что не стану казнить его.","9":"Но ты не должен оставить его безнаказанным. Ты мудр. Ты придумаешь, как надо поступить, чтобы он сошел в Шеол не своей смертью, чтобы кровь залила его седины…»","10":"И почил Давид с предками – был похоронен в Городе Давидовом.","11":"Сорок лет царствовал Давид над Израилем: в Хевроне – семь лет, в Иерусалиме – тридцать три года.","12":"Соломон воссел на престоле Давида, отца своего; и крепка была его власть.","13":"Адония, сын Хаггит, пришел к Вирсавии, матери Соломона. «С добром пришел?» – спросила она. «С добром», – отвечал Адония.","14":"И добавил: «У меня есть просьба к тебе». – «Говори», – ответила Вирсавия.","15":"Он сказал: «Ты знаешь, царство должно было стать моим; все израильтяне прочили меня в цари. Но царство досталось брату; так уж решил Господь.","16":"А я прошу тебя об одном. Не откажи мне». – «Говори», – сказала она.","17":"Он сказал: «Попроси царя Соломона (он тебе не откажет!), пусть отдаст мне в жены Авишаг шунамитянку». –","18":"«Хорошо, – ответила Вирсавия, – я поговорю о тебе с царем».","19":"И Вирсавия пошла к царю Соломону поговорить с ним об Адонии. Царь поднялся ей навстречу, поклонился ей, а потом, снова сев на трон, велел поставить рядом кресло для царицы – матери. Та села по правую руку от него и сказала:","20":"«У меня к тебе небольшая просьба. Не откажи мне!» – «Проси, мать моя, – ответил царь. – Я тебе не откажу».","21":"Она сказала: «Пусть Авишаг шунамитянку отдадут в жены твоему брату Адонии». –","22":"«Как? – сказал царь Соломон. – Ты просишь для Адонии всего лишь Авишаг шунамитянку? Проси уж для него сразу и царской власти! Он мой старший брат, за него и священник Авиафар, и Иоав, сын Церуи!»","23":"И царь Соломон поклялся Господом: «Пусть так-то и так-то покарает меня Бог, если Адония не заплатит жизнью за эту просьбу!","24":"Клянусь Господом, который возвел меня на престол отца моего Давида и, исполняя Свое обещание, возвеличил мой род: сегодня же Адония будет казнен!»","25":"Царь Соломон отдал приказ Бенае, сыну Иехояды, и тот убил Адонию.","26":"А священнику Авиафару Соломон приказал: «Ступай в Анатот, в свой земельный надел, – и там живи! Ты заслуживаешь смерти, но я сейчас не стану тебя казнить: ведь ты носил ковчег Господа Бога перед моим отцом Давидом и делил с моим отцом все невзгоды».","27":"Соломон отстранил Авиафара от должности священника Господа – и тем исполнил приговор, который Господь изрек роду Илия из Силома.","28":"О происходящем услышал Иоав, который был сторонником Адонии (сторонником Авессалома Иоав никогда не был). Он вбежал в Шатер Господа и схватился за рога жертвенника.","29":"Соломону доложили, что Иоав прибежал в Шатер Господа и что он у жертвенника. «Пойди и убей его!» – приказал Соломон Бенае, сыну Иехояды.","30":"Беная пришел в Шатер Господа и сказал Иоаву: «Царь приказал тебе выйти». – «Нет, – отозвался тот, – уж лучше я здесь умру». Беная передал царю ответ Иоава,","31":"и царь велел: «Вот так и сделай, как он сказал: убей его и похорони, чтобы очистить и меня, и весь наш род от пролитой Иоавом крови невинных.","32":"А вину за смерть Иоава пусть возложит Господь на него самого! Иоав убил двух людей, которые были доблестнее и лучше него: без ведома отца моего Давида он убил израильского военачальника Авнера, сына Нера, и иудейского военачальника Амасу, сына Иетера.","33":"Пусть вина за их смерть падет на голову Иоава и на головы его потомков – навеки! А Давиду и его потомкам, и роду его, и престолу его да дарует Господь благополучие – навеки!»","34":"Беная, сын Иехояды, пошел и убил Иоава. Иоав был похоронен в своем родовом наделе, в Пустыне.","35":"Вместо него Соломон поставил во главе войска Бенаю, сына Иехояды. А священника Цадока царь назначил на место Авиафара.","36":"Царь велел позвать Шими и сказал ему: «Построй себе дом в Иерусалиме, живи в нем и никуда не отлучайся.","37":"И знай: если ты отлучишься из дому и перейдешь Кедрон, ты будешь казнен и будешь сам виноват в своей смерти». –","38":"«Хорошо, – отвечал царю Шими, – как скажет господин мой, царь, так я, раб твой, и сделаю». И долгое время Шими жил в Иерусалиме.","39":"Но через три года случилось, что два раба, принадлежавших Шими, убежали к Ахишу, сыну Маахи, царю Гата. Шими сообщили: «Твои рабы находятся в Гате».","40":"Он оседлал осла и отправился в Гат к Ахишу требовать своих рабов назад. Сходил он туда и вернул своих рабов назад из Гата.","41":"Соломону доложили, что Шими ходил из Иерусалима в Гат и обратно.","42":"Царь велел позвать Шими и сказал: «Я ведь тебя предупреждал: „Если ты отлучишься и куда-нибудь отправишься, знай, что ты будешь казнен\". Я тебя заставил Господом поклясться. Ты мне сказал: „Хорошо, я все понял\".","43":"Как же мог ты не выполнить клятвы, данной пред Господом, и не исполнить моего приказа?»","44":"И царь сказал Шими: «Ты сам знаешь, отлично помнишь, какое зло ты причинил моему отцу Давиду. Пусть Господь обратит это зло на твою голову!","45":"А царь Соломон да будет благословен! И да будет престол Давидов вовеки неколебим пред лицом Господа!»","46":"Царь отдал приказ Бенае, сыну Иехояды, тот пошел и убил Шими. Соломон крепко держал власть в своих руках."},"3":{"1":"Соломон породнился с фараоном, царем Египта – женился на дочери фараона. Соломон поселил ее в Городе Давидовом, и она жила там до тех пор, пока он не достроил свой дворец, Храм Господа и стену вокруг Иерусалима.","2":"Народ по – прежнему приносил жертвы в капищах, так как Храм для имени Господа еще не был построен.","3":"Соломон любил Господа и следовал наставлениям своего отца Давида; однако жертвы он приносил в капищах.","4":"Соломон отправился в Гаваон, чтобы совершить жертвоприношение (там было самое большое из этих капищ), – и принес там на жертвеннике тысячу жертв всесожжения.","5":"Ночью в Гаваоне, во сне Соломону явился Господь. «Проси у Меня, что хочешь», – сказал Бог Соломону.","6":"Соломон сказал: «Ты оказывал моему отцу Давиду, рабу Твоему, великие милости, за то что он служил Тебе верой и правдой и всем сердцем был верен Тебе. И вот, не оставляя его Своей великой милостью, Ты возвел его сына на престол отца.","7":"О Господь, мой Бог! Ты сделал меня, раба Твоего, царем после моего отца Давида! Но я молод, неумел и несведущ,","8":"а вокруг меня, раба твоего, – народ, избранный Тобой, народ огромный; его не счесть, не исчислить.","9":"Дай же мне, рабу твоему, ясный разум, чтобы я мог править Твоим народом, различая добро и зло. Кому под силу править Твоим несметным народом?!»","10":"Понравились Господу эти слова – понравилось Ему, чего просит Соломон.","11":"И Бог сказал: «За эти слова – за то, что ты просишь не долголетия, не богатства, не смерти врагов твоих, а мудрость в делах суда и правления, –","12":"Я выполню твою просьбу и дарую тебе мудрость и разум. Не сравнится с тобой никто из предшественников, да и после тебя равных тебе не будет.","13":"Но Я дам тебе и то, о чем ты не стал просить: богатство и слава будут сопровождать тебя всю жизнь, и ни один царь не сравнится с тобой!","14":"И если ты будешь идти по пути, который Я заповедал, будешь следовать Моим законам и наставлениям, как твой отец Давид, то Я дарую тебе долголетие».","15":"Проснулся Соломон, но сон свой не забыл. Вернувшись в Иерусалим, Соломон предстал пред ковчегом договора с Господом, принес жертвы всесожжения и пиршественные жертвы и устроил пир для всех своих приближенных.","16":"В то время пришли к царю две публичные женщины. Предстали они перед царем,","17":"и одна из них сказала: «Господин мой! Мы с этой женщиной живем в одном доме. Я родила, она была тогда в доме.","18":"А через день родила и она. Мы были вдвоем, никого из чужих с нами не было, только мы с ней и были в доме.","19":"А ночью ее сын умер – она его задавила.","20":"Тогда она встала, ночью, пока я, раба твоя, спала, взяла у меня моего сына и положила его к себе, а своего, мертвого, мне подложила.","21":"Встала я утром покормить ребенка – он мертв! А когда рассвело, я присмотрелась – не мой это сын, не тот, кого я родила!» –","22":"«Нет, – говорит другая, – мой сын жив, а твой мертв!» – «Нет, – говорит та, – твой сын мертв, а мой жив!» Так и ругались они друг с другом перед царем.","23":"Царь сказал: «Одна говорит: „Мой сын жив, а твой мертв\", другая говорит: „Твой сын мертв, а мой жив\"»…","24":"И он велел принести ему меч. Принесли царю меч.","25":"«Разрубите живого ребенка пополам, – сказал царь. – Половинку отдайте одной, половинку – другой».","26":"И тогда та, что была матерью ребенка, затряслась от страха за свое дитя. «Господин мой! – сказала она царю. – Отдайте ей этого младенца живым. Не убивайте его!» А другая сказала: «Ни мне, ни тебе! Рубите».","27":"И царь сказал: «Отдайте этого младенца живым первой из двух. Не убивайте его! Та, что сказала так, – его мать!»","28":"Услышали израильтяне, как царь разрешил эту тяжбу, и всех охватил трепет перед царем. Они поняли: божественная мудрость дана ему, чтобы вершить суд."},"4":{"1":"Царь Соломон царствовал надо всем Израилем.","2":"Вот список главных его сановников. Азария, сын Цадока – священник,","3":"Элихореф и Ахия, сыновья Шиши , – писцы, Иосафат, сын Ахилуда – глашатай,","4":"Беная, сын Иехояды , – командующий войском, Цадок и Авиафар – священники,","5":"Азария, сын Нафана, – начальник над наместниками, Завуд, сын Нафана, – священник, царский советник,","6":"Ахишар – старший во дворце, Адонирам, сын Авды , – надзиратель за трудовой повинностью.","7":"Двенадцать наместников было у Соломона по всему Израилю. Они поочередно снабжали продовольствием царя и весь двор, каждый доставлял продовольствие по месяцу в год.","8":"Вот их имена. Сын Хура – на Ефремовых горах.","9":"Сын Декера – в Макаце, Шаалвиме, Бет – Шемеше и Элоне (Бет – Ханане).","10":"Сын Хеседа – в Арубботе; ему же подвластны были Сохо и вся страна Хефер.","11":"Сын Авинадава (он был женат на Тафат, Соломоновой дочери) – весь Нафат – Дор.","12":"Баана, сын Ахилуда, – Таанах, Мегиддо и весь Бет – Шеан близ Цартана, ниже Изрееля; от города Бет – Шеана до Авел – Мехолы и до мест, что лежат напротив Иокмоама.","13":"Сын Гевера – в Рамоте Галаадском; ему же были подвластны Деревни Яира (сына Манассии), лежащие в Галааде; ему же была подвластна область Аргов в Башане (шестьдесят больших городов со стенами и медными засовами).","14":"Ахинадав, сын Иддо , – в Маханаиме.","15":"Ахимаац (он тоже был женат на Соломоновой дочери, ее звали Босмат) – в Неффалиме.","16":"Баана, сын Хушая, – в Асире и Беалоте.","17":"Иосафат, сын Паруаха, – в Иссахаре.","18":"Шими, сын Элы , – в Вениамине.","19":"Гевер, сын Ури , – в земле Галаад (стране Сихона, царя аморейского, и Ога, царя башанского). И еще один наместник – в стране Иудейской…","20":"Люди Иуды и Израиля, бесчисленные, как песок морской, ели, пили и веселились.","21":"Соломону подвластны были все царства от Великой Реки до границы Египта (до страны филистимлян). Все они приносили Соломону дань и служили ему до самой его смерти.","22":"Ко двору Соломона каждый день доставлялось: тридцать коров пшеничной муки, шестьдесят коров ячменной муки,","23":"десять откормленных быков, двадцать быков с пастбищ, сто баранов, а кроме того олени, серны, косули и жирные гуси.","24":"Он был владыкой всего Заречья, от Тифсаха до Газы, – властвовал надо всеми царями Заречья. Со всеми окрестными державами у него был мир.","25":"Все время, пока царствовал Соломон, люди Иуды и Израиля, от Дана и до Беэр – Шевы, жили ничего не опасаясь средь своих лоз и смоковниц.","26":"У Соломона было сорок тысяч лошадиных упряжек для колесниц, а сверх того еще конницы двенадцать тысяч.","27":"…Эти наместники поочередно, по месяцу каждый, снабжали продовольствием царя Соломона и всех приглашенных к столу царя Соломона; ни в чем не было недостатка.","28":"Кроме того, каждый из этих наместников, в определенном ему количестве, доставлял в то место, где находился царь, ячмень и солому для лошадей и жеребцов.","29":"Бог дал Соломону мудрость, много знаний, ума – что песку на морском берегу.","30":"И превзошел Соломон своей мудростью всех мудрецов Востока и чародеев Египта.","31":"Он был мудрее всех людей на свете: мудрей Этана эзрахитянина, мудрей сыновей Махола – Хемана, Калкола и Дарды. Имя его было на устах у всех окрестных народов.","32":"Он изрек три тысячи притч, им сложены тысяча пять песен.","33":"Он рассуждал о всевозможных деревьях – от кедра, растущего на Ливане, до иссопа, что прорастает из щелей в стене. Он рассуждал о зверях, и о птицах, и о всяких мелких животных, и о рыбах.","34":"И приходили люди со всех стран света, чтобы послушать его мудрые речи, – посланцы всех царей земных, до которых дошла молва о мудрости Соломона."},"5":{"1":"Узнав, что Соломона помазали на царство и что он взошел на престол своего отца, Хирам, царь Тира, отправил к нему посольство, ведь Хирам всегда был в дружбе с Давидом.","2":"Царь Соломон велел передать Хираму:","3":"«Ты знаешь, что мой отец Давид не мог построить Храм для имени Господа, своего Бога: ему пришлось воевать с обступившими его врагами, пока Господь всех их не поверг к его ногам.","4":"А теперь, по воле Господа, моего Бога, вокруг полный покой: нет ни врагов, ни напастей.","5":"Я намерен построить Храм для имени Господа, Бога моего. Так ведь и предсказал Господь моему отцу Давиду: „Твой сын, которого Я возведу на престол твой после тебя, построит Храм для имени Моего\".","6":"Поэтому повели, чтобы нарубили для меня кедров на Ливане. Мои люди придут к твоим людям, и я заплачу тебе за труд твоих работников столько, сколько ты скажешь. Ты и сам знаешь, что нет у нас таких умелых лесорубов, как сидоняне».","7":"Услышав слова Соломона, Хирам обрадовался и сказал: «Благословен Господь, который даровал Давиду такого мудрого сына и поставил его править этим многолюдным народом!»","8":"И Хирам велел ответить Соломону: «Я выслушал твою просьбу и дам тебе все, что ты пожелаешь – и кедр, и кипарис.","9":"Мои люди будут спускать деревья с Ливанских гор к морю, оттуда я буду сплавлять плоты по морю к месту, которое ты мне назначишь, и разбирать их, а ты – принимай. Но ты тоже выполни мое желание: обеспечь мой двор продовольствием».","10":"И Хирам стал поставлять Соломону кедр и кипарис, сколько тому было нужно,","11":"а Соломон поставлял Хираму продовольствие для его двора: по двадцать тысяч коров пшеницы и по двадцать коров лучшего оливкового масла ежегодно.","12":"Господь, как и обещал, даровал Соломону мудрость. А между Хирамом и Соломоном был мир, скрепленный договором.","13":"Царь Соломон заставил весь Израиль нести трудовую повинность: собрал для работ тридцать тысяч человек","14":"и отправлял их посменно на Ливанские горы, по десять тысяч человек каждый месяц. Один месяц проводили они на Ливанских горах, и два месяца – у себя дома. Надзирателем за трудовой повинностью был Адонирам.","15":"Кроме того, у Соломона было семьдесят тысяч носильщиков и восемьдесят тысяч каменотесов в горных каменоломнях.","16":"И еще у Соломона было три тысячи триста распорядителей работ, которые руководили рабочими.","17":"По приказу царя в каменоломнях вырубали огромные дорогостоящие плиты, чтобы фундамент Храма был из тесаного камня.","18":"Их обтесывали Соломоновы строители вместе со строителями Хирама и людьми из Библа. Так были заготовлены древесина и камень для постройки Храма."},"6":{"1":"В четыреста восьмидесятый год после исхода израильтян из Египта, в четвертый год царствования Соломона над Израилем, в месяце зив (это второй месяц года) начал Соломон строить Храм Господа.","2":"Храм, построенный царем Соломоном для Господа, имел шестьдесят локтей в длину, двадцать локтей в ширину и тридцать локтей в высоту.","3":"Притвор перед храмовым залом имел двадцать локтей в ширину (в соответствии с шириной Храма) и выступал вперед, перед Храмом, на десять локтей.","4":"В Храме Соломон сделал глухие окна, с карнизами, вокруг стены Храма он построил ярус пристроек – построил стены вокруг всего Храма (то есть вокруг храмового зала и святилища) и по всему периметру устроил боковые комнаты.","6":"Ширина нижнего яруса пристройки – пять локтей, ширина среднего яруса – шесть локтей, ширина третьего яруса – семь локтей; стена Храма была сделана снаружи ступенчатой, чтобы не вделывать перекрытия ярусов в стену Храма.","7":"(Храм строился из цельных камней, доставленных готовыми из каменоломни, и не было слышно на стройке ни молота, ни тесла, ни иного железного орудия.)","8":"Вход в средний ярус боковых комнат был на южной стороне Храма. По лестнице с нижнего яруса поднимались на средний, а оттуда на верхний.","9":"Завершив возведение Храма, Соломон облицевал Храм кедровыми панелями и пилястрами.","10":"Вокруг всего Храма он сделал ярус пристроек, высотой по пять локтей, их кедровые балки опирались на стену Храма.","11":"И было Соломону слово Господа:","12":"«Ты строишь Храм – и если ты будешь следовать Моим законам, исполнять Мои повеления и соблюдать Мои заповеди, то Я при тебе исполню обещание, которое дал когда-то твоему отцу Давиду:","13":"Я поселюсь средь сынов Израилевых и никогда уже не оставлю народ Мой, Израиль!»","14":"Завершив возведение Храма,","15":"Соломон изнутри облицевал стены Храма кедровыми досками – от пола Храма до потолочных балок он покрыл стены изнутри деревом. Пол Храма он сделал из кипариса.","16":"На расстоянии в двадцать локтей от задней стены Храма он поставил внутри Храма перегородку из кедровых досок, от пола до потолка, и за этой перегородкой устроил святилище – святыню святынь.","17":"Сорок локтей была длина Храма (храмового зала) перед святилищем.","18":"(Весь Храм изнутри был облицован кедром с резными изображениями бутонов и распустившихся цветов; всюду был кедр, камня нигде не было видно.)","19":"Это святилище внутри Храма он устроил для того, чтобы поместить в него ковчег договора с Господом;","20":"оно имело двадцать локтей в длину, двадцать локтей в ширину и двадцать локтей в высоту. Соломон обил стены святилища чистым золотом. Жертвенник он облицевал кедром.","21":"Соломон покрыл Храм изнутри чистым золотом, протянул золотые цепи перед святилищем и само святилище обил золотом.","22":"Весь Храм он покрыл золотом – совершенно, полностью. И жертвенник, что перед святилищем, он целиком покрыл золотом.","23":"В святилище Соломон поставил двух херувимов, вырезанных из масличного дерева. Высота каждого – десять локтей.","24":"Длина одного крыла у каждого из херувимов – пять локтей, длина другого крыла – тоже пять локтей. У одного херувима размах крыльев – десять локтей;","25":"и у другого херувима – десять локтей. Одинаковых размеров и одинаковой формы были оба херувима.","26":"Высота одного херувима – десять локтей, высота другого – десять локтей.","27":"Соломон поставил херувимов во внутренней части Храма. Крылья у херувимов были распростерты: один касался крылом одной стены, другой касался крылом другой стены; а крылья, обращенные внутрь Храма, касались друг друга.","28":"Соломон покрыл этих херувимов золотом.","29":"Все стены Храма, и во внутреннем помещении, и во внешнем, он украсил резными изображениями херувимов, финиковых пальм и распустившихся цветов.","30":"Пол во внутреннем и внешнем помещениях Храма он покрыл золотом.","31":"Для входа в святилище он сделал двери из масличного дерева, косяки их были пятиступенчатыми.","32":"На обеих дверях масличного дерева он сделал резные изображения херувимов, пальм и распустившихся цветов и обил их золотом – покрыл золотом и херувимов, и пальмы.","33":"Точно таким же он сделал и вход в храмовый зал, только косяки из масличного дерева здесь были четырехступенчатые,","34":"а двери были сделаны из кипариса. Одна створка состояла из двух поворачивающихся частей и другая створка тоже состояла из двух поворачивающихся частей.","35":"На них он вырезал херувимов, пальмы и распустившиеся цветы, а резьбу покрыл позолотой.","36":"Внутренний храмовый двор он обнес оградой: на каждые три ряда каменной кладки – ряд кедровых бревен.","37":"В четвертый год заложен был Храм, в месяц зив,","38":"а в одиннадцатый год, в месяц бул (восьмой месяц года), Храм был завершен – отделаны все детали, сделано все, что задумано. Семь лет строил его Соломон."},"7":{"1":"А свой дворец Соломон строил тринадцать лет – столько понадобилось на то, чтобы завершить все работы.","2":"Соломон построил Зал Ливанского Леса. Длина его – сто локтей, ширина – пятьдесят локтей, высота – тридцать локтей. В нем было четыре ряда кедровых колонн, перекрытых кедровыми балками.","3":"Потолок из кедра поддерживался брусьями, которые опирались на колонны (их было сорок пять, по пятнадцать в каждом ряду).","4":"В три ряда шли карнизы, и проемы шли тремя рядами друг напротив друга.","5":"Косяки всех дверей были четырехступенчатые, с карнизами. (Проемы шли тремя рядами друг напротив друга.)","6":"И еще Соломон построил Колонный притвор. Длина притвора была пятьдесят локтей, ширина – тридцать локтей, а перед ним был портик: колонны и навес.","7":"И еще Соломон построил притвор, где, восседая на престоле, вершил суд, – Зал Суда, облицованный кедром с пола до потолка.","8":"Жилые покои Соломона находились в отдельном дворе – не в том, где Притвор – но построены были так же. И дворец для дочери фараона, которую Соломон взял себе в жены, он тоже строил так же, как Притвор.","9":"Все эти здания, от фундамента до парапета под кровлей, были сложены из дорогостоящих каменных плит, подогнанных по размеру, тесаных; поверхности этих плит, выходившие на наружную и внутреннюю стены, были обработаны пилой.","10":"На фундаменте из дорогостоящих каменных плит огромной величины – по десять и по восемь локтей –","11":"стояли стены из дорогостоящих каменных плит, подогнанных по размеру, и кедровых бревен.","12":"Большой двор Соломон обнес оградой: на каждые три ряда каменной кладки – ряд кедровых бревен. Таким же был и внутренний двор Храма Господнего, а также двор Притвора.","13":"Царь Соломон пригласил Хирама из Тира.","14":"Хирам был сыном одной вдовы из племени Неффалимова, а отец его был тирянин, медник; и был этот Хирам сведущ, умел и искусен во всяческой работе с медью. Прибыл он к царю Соломону и выполнил все, что было ему поручено.","15":"Хирам отлил две медные колонны. Высота каждой колонны – восемнадцать локтей, окружность, если померить шнурком, – двенадцать локтей.","16":"И еще он сделал две капители, литые, медные, чтобы увенчать ими эти колонны. Высота одной капители – пять локтей, высота второй – тоже пять локтей,","17":"а вокруг этих капителей на вершинах колонн – переплетенье плетенок и кружево цепочек. Вокруг одной капители – плетенка, и вокруг другой капители – плетенка.","18":"Еще он сделал гранатовые плоды, которые в два ряда опоясывали плетенку, покрывавшую капитель на вершине первой колонны; точно так же он украсил и капитель второй колонны.","19":"Капители на вершине колонн (в притворе) имели форму цветка лотоса, высотой в четыре локтя;","20":"они возвышались над основанием капители, которое было скрыто плетенкой. Двести гранатовых плодов, расположенных рядами, опоясывали обе капители.","21":"Колонны он поставил в притворе Храма. Воздвигнув правую колонну, он дал ей имя «Яхин», воздвигнув левую – дал ей имя «Боаз».","22":"Обе колонны были увенчаны капителями в виде цветков лотоса. Окончив работу над колоннами,","23":"Хирам сделал Море – литое, круглое; в десять локтей от края до края; высота его – пять локтей; окружность, если померить шнурком, – тридцать локтей.","24":"По краю Моря, по кругу, шли изображения цветочных бутонов. Они опоясывали все Море (в десять локтей размером) двумя рядами и были отлиты вместе с Морем как единое целое.","25":"Море покоилось на двенадцати быках. Три быка смотрели на север, три – на запад, три – на юг, три – на восток; крупы их были обращены внутрь, а Море лежало на них сверху.","26":"Толщина стенки Моря – одна ладонь; край его был как край чаши, в виде цветка лотоса. Вместимость Моря – две тысячи батов.","27":"Хирам сделал десять медных подставок. Длина каждой подставки – четыре локтя, ширина – четыре локтя, высота – три локтя.","28":"Вот как эти подставки были устроены. Каждая состояла из панелей, крепящихся между стойками.","29":"На этих панелях, крепящихся между стойками, были изображены львы, быки и херувимы. Такие же изображения были и на самих стойках. Сверху и снизу от этих львов и быков – витой узор чеканной работы.","30":"У каждой подставки – по четыре медных колеса с медными ступицами и по четыре ноги (подпорки) – внизу, под чаном. Подпорки были литые, покрытые витым узором.","31":"Изнутри подставки вверх шло горлышко – круглое гнездо, глубиной в полтора локтя. Вокруг отверстия – изображения. Сам же корпус подставки не круглый, а квад – ратный*","32":"Под панелями подставки – четыре колеса; оси колес крепились к подставке. Высота каждого колеса – полтора локтя.","33":"Колеса были устроены как колеса у колесниц, но и оси, и ободья, и спицы, и ступицы – все было литое.","34":"По углам каждой подставки было по подпорке, они были отлиты как единое целое с подставкой.","35":"Над подставкой ободок, высотой в поллоктя. И еще над подставкой были ручки, отлитые как одно целое вместе с панелями.","36":"Поверхности ручек и панелей покрыты резными изображениями херувимов, львов и пальм, а вокруг – витой узор.","37":"Так сделал Хирам десять подставок. Все они были одинаково отлиты, одного размера и одной формы.","38":"Еще он сделал десять медных чанов – по одному чану для каждой из десяти подставок. Вместимость каждого чана – сорок батов, диаметр – четыре локтя.","39":"Пять подставок Хирам поместил справа от входа в Храм и пять – слева от входа. Море поместил справа от входа в Храм, возле юго – восточного угла.","40":"Еще Хирам сделал котлы, лопатки и чаши для кропления кровью. Так завершил он все работы, которые выполнял для царя Соломона в Храме Господа:","41":"колонны (две); чашевидные капители на вершинах колонн (две); плетенки, покрывающие чашевидные капители на вершинах колонн (две);","42":"плоды гранатовые на двух плетенках (четыреста; по два ряда плодов на каждой из плетенок, покрывающих чашевидные капители колонн);","43":"подставки (десять); чаны, стоящие на подставках (десять);","44":"медное Море (одно); быки, поддерживающие медное Море (двенадцать);","45":"а также котлы, лопатки и чаши для кропления кровью. Все эти вещи, которые Хирам сделал по заказу царя Соломона для Храма Господа, были из полированной меди.","46":"(Царь отливал их в Иорданской долине, близ бродов Адамы, между Суккотом и Цартаном.)","47":"Расставил Соломон всю эту утварь – и было ее столько, что даже счету не поддавалось, сколько меди пошло на нее.","48":"И еще изготовил Соломон всякую утварь для Храма Господа: золотой жертвенник; золотой стол для хлеба, что должен лежать пред лицом Господа;","49":"светильники из чистого золота (пять справа от входа в святилище и пять – слева); золотые цветки, лампады, щипцы;","50":"чаши, ножницы, чаши для кропления кровью, ложки для благовоний, кадильницы из чистого золота, а также золотые накладки для дверей внутренней части Храма (святыни святынь) и храмового зала.","51":"Завершив все работы по строительству Храма Господа, царь Соломон перенес туда дары, которые его отец Давид посвятил Господу – серебро и золото и прочую утварь – и поместил их в сокровищницу Храма Господа."},"8":{"1":"И вот созвал Соломон старейшин Израиля, всех глав племен и вождей родов израильских к себе, в Иерусалим, чтобы вынести ковчег договора с Господом из Города Давидова (Город Давидов – это Сион).","2":"Все израильтяне собрались к царю Соломону на Праздник в месяце этаниме (это седьмой месяц года).","3":"Когда пришли все старейшины Израиля, священники подняли ковчег","4":"и понесли. И ковчег Господень, и шатер Встречи, и всю священную утварь, что была в шатре – все это понесли священники и левиты.","5":"А царь Соломон и вся созванная им община Израиля находились перед ковчегом; и столько баранов и быков принесли они в жертву, что не счесть их было, не пересчитать.","6":"Священники поставили ковчег договора с Господом в назначенном ему месте, в святилище Храма, в святыне святынь, под сенью крыл херувимовых.","7":"Херувимы простирали крылья над местом, где находился ковчег, осеняя ковчег и шесты для ношения ковчега.","8":"Шесты эти были такими длинными, что концы их были видны из храмового зала перед внутренним святилищем; но снаружи они не были видны. Так расположены они и по сей день.","9":"В ковчеге не было ничего, кроме двух каменных таблиц, которые положил туда Моисей на Хориве, где Господь заключил договор с израильтянами после их ухода из Египта.","10":"И лишь только священники вышли из Храма, как облако наполнило Храм Господень.","11":"И не могли священники из-за этого облака стоять и продолжать свою службу: это слава Господня наполнила собой Храм Господень.","12":"И сказал Соломон: Во мгле Господь пожелал обитать!","13":"Дворец высокий Тебе я возвел – жилище, где Ты пребудешь вовек!","14":"Повернувшись лицом к общине Израиля – вся община Израиля стояла перед ним – царь благословил ее","15":"и сказал: «Благословен Господь, Бог Израиля! Ныне исполнил Он то, что обещал отцу моему, Давиду. Господь говорил:","16":"„С тех пор как Я вывел Мой народ, Израиль, из Египта, не избирал Я во владениях племен Израилевых ни одного города, в котором будет построен Храм для имени Моего, и никого не избирал правителем над Моим народом, Израилем. Ныне же Я избираю Иерусалим, чтобы там пребывало имя Мое, и избираю Давида – править Моим народом\".","17":"Мой отец Давид задумал построить Храм для имени Господа, Бога Израилева,","18":"но Господь сказал моему отцу Давиду: „Ты хочешь построить Храм для имени Моего – это ты хорошо задумал.","19":"Но все же построишь его не ты, а твой сын, рожденный от семени твоего\".","20":"И вот Господь исполнил Свое обещание: я наследовал отцу моему Давиду и воссел на престоле израильском, по слову Господа. Я построил Храм для имени Господа, Бога Израилева,","21":"и поместил в нем ковчег, где хранится договор с Господом, который Господь заключил с нашими отцами, когда вывел их из Египта».","22":"Соломон в присутствии всей общины Израиля стал перед жертвенником Господа, простер руки к небу","23":"и сказал: «Господи, Боже Израилев! Нет бога, равного Тебе, ни на небе вверху, ни на земле внизу! Ты соблюдаешь договор с рабами Твоими, и хранишь верность тем, кто служит Тебе всем сердцем.","24":"Ты верен обещанию, которое дал рабу Твоему Давиду, отцу моему: что изрек Ты Своими устами, то ныне исполнил рукой Своей.","25":"Будь же верен и другому обещанию, которое Ты дал рабу Твоему Давиду, отцу моему. Ты сказал ему: „Если твои потомки будут верно следовать по пути, который Я заповедал им, если будут служить Мне, как ты Мне служил, то никогда они не будут отторгнуты от лица Моего, всегда будут они на престоле Израиля\".","26":"Боже Израилев! Пусть сбудутся слова, которые Ты сказал рабу Твоему Давиду, моему отцу.","27":"Поистине, Богу ли жить на земле?! Небеса и небеса небес не могут вместить Тебя – тем более этот дом, мною построенный.","28":"Услышь молитву и прошение раба Твоего, Господи, Боже мой! Услышь вопль и молитву, которую раб Твой ныне обращает к Тебе!","29":"Да будут очи Твои взирать на этот Храм и ночью, и днем – на это место, о котором сказал Ты: „Там пребудет имя Мое\"; и услышь всякую молитву, с которой раб Твой сюда обратится.","30":"Услышь всякое прошение раба Твоего и народа Твоего Израиля: сюда будут они обращаться с молитвами, а Ты услышь их из своей небесной обители – услышь и помилуй!","31":"Если кто-то будет обвинен в грехе против ближнего, и должен будет клятвой доказать свою невиновность, и придет, и поклянется перед Твоим жертвенником в этом Храме –","32":"услышь с небес и рассуди рабов Твоих. Пусть станет явной вина виновного и воздастся ему по делам его, пусть станет явной правда правого и воздастся ему за праведность его.","33":"Если народ Твой Израиль будет разбит врагом в сражении, за то, что согрешил пред Тобою, но покается, и восславит Твое имя, и будет молиться Тебе и просить Тебя в этом Храме –","34":"услышь с небес эту молитву, прости грех народа Твоего Израиля, верни их в страну, которую Ты дал отцам их.","35":"Если небеса затворятся и не будет дождя, за то, что сыны Израилевы согрешили пред Тобою, и они обратятся сюда с молитвами, и восславят Твое имя, и покаются в грехах своих, за которые Ты их караешь, –","36":"услышь с небес эту молитву, прости грех рабов Твоих – народа Твоего Израиля, и укажи им путь, по которому они должны идти, и ниспошли дождь на землю Твою, которую Ты дал Своему народу во владение.","37":"И если случится в стране голод, если случится мор, если погибнет хлеб от суховея или спорыньи, если налетит саранча, если враг осадит город – какая бы беда и напасть ни случились,","38":"о чем бы ни молил Тебя, о чем бы ни просил Тебя кто-нибудь из народа Твоего Израиля, в скорби сердца простирая руки к этому Храму,","39":"услышь его молитву из Своей небесной обители и исполни его прошение! Воздай каждому по делам его, зная, что на сердце у него, – ведь один лишь Ты знаешь, что на сердце у человека.","40":"И пусть они боятся и почитают Тебя всю жизнь, пока живут на земле, которую Ты даровал отцам их.","41":"И даже если чужеземец, не принадлежащий к народу Твоему Израилю, придет из дальней страны ради имени Твоего","42":"(ведь и туда дойдет слух о великом Твоем имени, о руке Твоей могучей, деснице простертой) – если придет он и помолится перед этим Храмом,","43":"то услышь его с небес, из вечного жилища Твоего, и исполни все, о чем он попросит. Пусть все народы земли знают имя Твое, пусть они боятся и почитают Тебя так же, как Тебя почитает народ Твой Израиль, и пусть знают, что именем Твоим осенен этот Храм, мною построенный.","44":"Если народ Твой пойдет на войну с врагами – туда, куда Ты его поведешь, – и будет молиться Господу, обратясь лицом к городу, который Ты избрал, и к Храму, который я построил для имени Твоего, –","45":"то услышь с небес их молитву и прошение, будь им заступником.","46":"Если согрешат сыны Израилевы пред Тобою (ибо нет человека, который бы не грешил!) и, прогневавшись на них, Ты отдашь их в руки врагу, и уведут их в плен, угонят в землю врагов, далекую или близкую, –","47":"и если там, в той стране, где они будут в плену, они всем сердцем раскаются, – если там, в стране тех, кто взял их в плен, они станут Тебя умолять и скажут: „Согрешили мы, преступны мы и виновны\", –","48":"если там, в стране врагов, которые взяли их в плен, они обратятся к Тебе всем сердцем и всей душою, если станут молиться Тебе, обратясь лицом к стране, которую Ты дал их отцам, к городу, который Ты избрал, и к Храму, который я построил для имени Твоего, –","49":"услышь тогда с небес, из Твоего жилища, их молитву и прошение! Будь им заступником.","50":"Прости народ Твой, который согрешил пред Тобою, прости им все их прегрешения и сделай, чтобы взявшие их в плен стали к ним милосердны и оказали им свою милость.","51":"Ибо это Твой народ, Твое достояние; Ты вы – вел их из Египта, как из печи плавильной.","52":"Да будут очи Твои благосклонно взирать на прошения раба Твоего и на прошения народа Твоего Израиля! Услышь их, когда воззовут они к Тебе.","53":"Ведь Ты избрал их из всех народов земли, чтобы сделать Своим достоянием – так провозгласил Ты через раба Своего Моисея, когда вел отцов наших из Египта, Господи Боже!»","54":"Когда Соломон окончил свою молитву Господу, когда произнес он все эти молитвы и прошения, стоя на коленях перед жертвенником Господа и воздев руки к небесам, он встал","55":"и громко благословил всю общину Израиля:","56":"«Благословен Господь, даровавший покой народу Своему Израилю, как и обещал. Ничто из того, что Он обещал через раба Своего Моисея, не осталось неисполненным.","57":"Да будет Господь, Бог наш, с нами, как был с нашими отцами, да не оставит Он нас и не покинет,","58":"да обратит к Себе наши сердца, чтобы мы ходили путями Его, чтобы исполняли заповеди, повеления и законы, которые дал Он отцам нашим!","59":"И пусть слова молитвы, которую я вознес Господу, будут пред Господом, Богом нашим, день и ночь, чтобы был Он изо дня в день заступником и мне, рабу Своему, и всему народу Своему Израилю.","60":"Да узнают все народы земли, что Господь есть Бог и нет иного!","61":"Пусть сердца ваши будут всецело преданы Господу, Богу нашему, чтобы вы, как и ныне, жили по Его законам и соблюдали Его заповеди!»","62":"Царь и все израильтяне совершили жертвоприношения Господу.","63":"Соломон принес Господу пиршественные жертвы: двадцать две тысячи быков и сто двадцать тысяч баранов. Так царь и все израильтяне торжественно освятили Храм Господень.","64":"В тот же день царь освятил место посреди двора, что перед Храмом Господа, и принес там жертвы всесожжения, а также хлебное приношение и жир пиршественных жертв (медный жертвенник, стоявший пред лицом Господа, был слишком мал для такого всесожжения, для такого хлебного приношения и для жира этих пиршественных жертв).","65":"И устроил Соломон праздник. Весь Израиль – великое множество народа от Лево - Хамата до Египетской ложбины – праздновал вместе с Соломоном пред лицом Господа, нашего Бога, в течение семи дней и еще семи дней (всего четырнадцать дней).","66":"На восьмой день царь отпустил народ. Люди благословили царя и разошлись по домам, радостные и довольные тем, как много добра сделал Господь для Давида, раба Своего, и для Израиля, народа Своего."},"9":{"1":"После того как Соломон завершил строительство Храма Господнего и царского дворца, а также другие задуманные им постройки,","2":"Господь явился Соломону во второй раз – как прежде являлся в Гаваоне –","3":"и сказал: «Я услышал твою молитву, твое прошение, ко Мне обращенное. Я избрал и освятил этот Храм, который ты построил, и Мое имя будет вечно обитать в нем; и всегда будут обращены к нему очи Мои и сердце Мое.","4":"И если ты будешь служить Мне, как служил отец твой Давид, от всего сердца и честно, во всем будешь поступать так, как Я тебе повелел, если будешь соблюдать Мои повеления и законы –","5":"то вечной Я сделаю твою власть над Израилем. Ведь Я дал обещание твоему отцу Давиду: „Твои потомки всегда будут на престоле Израиля\".","6":"Но если вы или ваши дети отступите от Меня, если не будете соблюдать Мои повеления и законы, которые Я установил для вас, а станете служить и поклоняться другим богам,","7":"то Я смету Израиль прочь с той земли, которую даровал ему, и отвергну Храм, который Я избрал для имени Моего. Тогда все народы будут глумиться над Израилем и поносить его.","8":"А Храм этот станет руинами, и всякий, кто пройдет мимо, ужаснется и присвистнет, и спросит: „Отчего так поступил Господь с этой страною и с этим Храмом?\"","9":"И ему ответят: „Оттого, что забыли они своего Бога, Господа, который вывел их отцов из Египта, и последовали за другими богами, стали поклоняться им и служить им. Вот за что обрушил на них Господь все эти беды\"».","10":"В течение двадцати лет Соломон строил два здания – Храм Господа и царский дворец.","11":"Хирам, царь Тира, доставлял ему кедр, кипарис и золото, сколько бы Соломон ни пожелал. А Соломон тогда передал Хираму двадцать городов в Галилее.","12":"Отправился Хирам из Тира, чтобы осмотреть города, подаренные ему Соломоном, и они ему не понравились.","13":"Он сказал: «Что же это за города такие ты дал мне, брат мой?» (С тех пор и доныне эта область зовется «Кавул».)","14":"И уплатил Хирам царю сто двадцать талантов золота.","15":"Теперь о трудовой повинности, которую Соломон возложил на народ, чтобы построить Храм Господа и свой дворец, а также Милло, стены Иерусалима, Хацор, Мегиддо и Гезер.","16":"Фараон, царь Египта, пришел и захватил Гезер, сжег его, перебил жителей города – ханаанеев и дал его в приданое своей дочери, жене Соломона.","17":"Соломон заново отстроил Гезер, Нижний Бет – Хорон,","18":"Баалат, Тамар (в пустыне, в стране Иудейской),","19":"а также все принадлежавшие ему крепости со складами, и крепости для колесниц, и крепости для конницы. В Иерусалиме, и на Ливане, и по всей подвластной ему стране Соломон построил все, что задумал.","20":"На всех, кто еще оставался из амореев, хеттов, периззеев, хиввеев и евусеев – на всех неизраильтян,","21":"потомков тех, кто остался в этой стране, из-за того что израильтяне не смогли истребить их, – Соломон возложил трудовую повинность. Эту трудовую повинность они несут и поныне.","22":"А израильтян Соломон не принуждал к работам: они были у него воинами, приближенными, чиновниками, начальниками стражи, начальниками колесничного войска и конницы.","23":"Вот распорядители работ, которые у Соломона управляли народом и руководили рабочими, – их было пятьсот пятьдесят человек.","24":"Дочь фараона переселилась из Города Давидова в собственный дворец, который построил для нее Соломон. Тогда же Соломон застроил Милло.","25":"Соломон трижды в год приносил жертвы всесожжения и пиршественные жертвы на жертвеннике, который он построил для Господа, – возносил дым жертв перед Господом. Так завершилось строительство Храма.","26":"А еще царь Соломон построил корабли в Эцион – Гевере, что близ Элата, на берегу моря Суф, в стране Эдом.","27":"Хирам отправил на этих кораблях, вместе с людьми Соломона, своих людей – опытных моряков.","28":"Они приплыли в страну Офир, взяли там четыреста двадцать талантов золота и привезли царю Соломону."},"10":{"1":"Услышала царица Савская молву о Соломоне, о славе имени Господнего, – и пришла испытать Соломона загадками. Юна прибыла в Иерусалим с огромным караваном верблюдов, груженных благовониями, несметным количеством золота и драгоценными камнями, пришла к Соломону и говорила с ним обо всем, о чем хотела.","3":"Но о чем бы она ни спросила, Соломон отвечал ей – не было такого вопроса, который был бы неясен для царя и на который он не мог бы ей ответить.","4":"Узнала царица Савская, какая у Соломона мудрость, увидала, какие постройки он построил,","5":"и что подают у него за трапезой, и как рассаживаются его приближенные, и как прислуживают его слуги, и как все одеты, и что пьют они, и какие всесожжения приносит он в Храме Господа – и дух у нее захватило.","6":"Так сказала она царю: «Значит, правду слышала я у себя в Саве о твоих деяниях и твоей мудрости.","7":"Я не верила слухам, но теперь пришла и своими глазами вижу – мне не рассказали и половины! Мудрость и богатства твои превосходят все, что я о тебе слышала.","8":"Счастливы твои люди, счастливы твои приближенные, что они всегда рядом с тобою и слышат твою мудрую речь!","9":"Благословен твой Бог, Господь, благоволивший ради извечной любви Своей к Израилю дать тебе израильский престол и поставивший тебя царем, чтобы творил ты правду и суд!»","10":"Она подарила царю сто двадцать талантов золота, несметное количество благовоний и драгоценные камни. Никогда еще не привозили такого количества благовоний, как привезла царица Савская в дар царю Соломону.","11":"(А Хирамовы корабли, ходившие в Офир за золотом, привезли из Офира очень много дерева альмуг и драгоценных камней.","12":"Из дерева альмуг царь сделал украшения в Храме Господа и во дворце, а также арфы и лиры для музыкантов. С тех пор и доныне столько дерева альмуг не привозили и даже не видели.)","13":"Царь Соломон дал царице Савской все, чего пожелала она и попросила, а сверх того – что сам захотел дать, с царской, Соломоновой, щедростью. И пустилась она в обратный путь, в страну свою, со своим караваном.","14":"Каждый год Соломон получал шестьсот шестьдесят шесть талантов золота –","15":"это не считая податей, торговых доходов и дани, поступавшей от всех царей Аравии и от наместников провинций.","16":"Царь Соломон сделал двести больших щитов, обитых золотом (на каждый такой щит пошло по шестьсот шекелей золота),","17":"и триста малых щитов (на каждый такой щит пошло по три мины золота). Эти щиты царь поставил в Зале Ливанского Леса.","18":"Еще сделал Соломон трон из слоновой кости, обитый чистым золотом.","19":"Шесть ступеней было у этого трона и круглая сверху спинка, а справа и слева подлокотники, и у каждого из подлокотников стояло по льву.","20":"А на шести ступенях стояло двенадцать львов, по одному на каждой ступени с каждой стороны. Ни в одном царстве никогда такого не было.","21":"А кубки у царя Соломона были все золотые, и вся утварь Зала Ливанского Леса была из чистого золота; серебра не было – его во времена царя Соломона не ставили ни во что.","22":"Ведь у царя были на море таршишские корабли (вместе с флотом Хирама), которые каждые три года привозили золото, серебро, слоновую кость, обезьян и павлинов.","23":"Соломон превзошел всех царей земли богатством и мудростью.","24":"Весь мир жаждал увидеть Соломона и послушать ту мудрость, которую вложил ему в сердце Бог.","25":"И каждый, приезжая, приносил свой дар: серебряные вещи, золотые вещи, одеяния, оружие, благовония, коней и мулов – и так год за годом.","26":"Соломон создал колесничное и конное войско: колесниц у него было тысяча четыреста, а конницы – двенадцать тысяч. Он разместил их в крепостях, специально отведенных для колесничного войска, а также у себя в Иерусалиме.","27":"В его правление серебра в Иерусалиме было – что камней, кедра – что сикомор в Предгорье.","28":"Лошадей Соломону доставляли из Египта и из Куэ: царские купцы покупали их в Куэ.","29":"Колесница, доставленная из Египта, обходилась в шестьсот шекелей серебра, а лошадь – во сто пятьдесят шекелей. Затем купцы поставляли их всем хеттским и арамейским царям."},"11":{"1":"Царь Соломон любил своих многочисленных жен – чужестранок; помимо дочери фараона у него были и моавитянки, и аммонитянки, и эдомитянки, и сидонянки, и хеттянки.","2":"Господь сказал израильтянам об этих народах: «Вы не должны вступать с ними в родство – ни жениться, ни выдавать дочерей замуж – иначе они переманят вас к своим богам». А Соломон полюбил этих женщин:","3":"у него было семьсот жен – цариц и триста наложниц. И вот, эти женщины сбили его с пути:","4":"когда он состарился, они переманили его к другим богам. Не был Соломон – в отличие от своего отца Давида – всей душою предан Господу, Богу своему. Юн поклонялся Астарте, сидонской богине, и Милкому, аммонской скверне,","6":"и творил дела, ненавистные Господу. Не был он – в отличие от своего отца Давида – всецело привержен Господу.","7":"И тогда построил Соломон капище Кемоша, моавской скверны, – на горе, что к востоку от Иерусалима, – а также капище Молоха, аммонской скверны.","8":"Так стал он делать для всех своих жен – чужестранок, чтобы они приносили жертвы своим богам и воссылали им жертвенный дым.","9":"Господь прогневался на Соломона, ибо Соломон отвернулся от Господа, Бога Израиля, который дважды являлся ему","10":"и велел не почитать иных богов. А Соломон не исполнил Его воли.","11":"«За то, что ты так поступаешь, – сказал Господь Соломону, – за то, что ты не соблюдаешь договор со Мной и не следуешь законам, которые Я дал тебе, Я вырву царскую власть из твоих рук и отдам твоему рабу.","12":"Пока ты жив, Я этого не сделаю – ради твоего отца Давида – но Я вырву царскую власть из рук твоего сына.","13":"Впрочем, не все царство Я отниму у него: ради раба Моего Давида и ради Иерусалима, города, который Я избрал, Я оставлю твоему сыну власть над одним племенем».","14":"И наслал Господь на Соломона врага: Хадада – эдомитянина. Хадад был из рода эдомских царей.","15":"Когда Давид воевал в Эдоме, Иоав, военачальник Давида, отправился похоронить павших там воинов; все мужское население Эдома было вырезано.","16":"Шесть месяцев провело там израильское войско под командованием Иоава, пока не истребило всех мужчин в Эдоме.","17":"Но Хадад и некоторые из эдомитян, вельмож его отца, бежали в Египет. Хадад тогда был еще мальчиком.","18":"Покинув Мидьян, они достигли Парана, где к ним присоединились люди из Парана. Они пришли в Египет, к фараону, царю египетскому, и фараон обеспечил Хадада и кровом, и пищей, и даже наделил его землей.","19":"Фараон хорошо относился к Хададу и выдал за него сестру своей жены, царицы Тахпенес,","20":"и та родила ему сына Генувата. Когда Генуват подрос, Тахпенес взяла его во дворец фараона, он воспитывался во дворце фараона, вместе с египетскими царевичами.","21":"Но вот однажды Хадад, живя в Египте, узнал, что Давид почил с предками и что военачальник Иоав тоже умер. «Дозволь мне отправиться на родину», – сказал Хадад фараону.","22":"«Ты хочешь вернуться на родину? – спросил фараон. – Тебе чего-то недостает при моем дворе?» – «Нет, – отвечал Хадад. – Но разреши мне вернуться…»","23":"И еще одного врага наслал Господь на Соломона: Резона, сына Эльяда. Этот Резон убежал от своего господина, Хададэзера, царя Цовы ,","24":"и набрал собственный отряд. После побоища, которое устроил там Давид, они пошли в Дамаск, заняли его и сделали Резона царем Дамаска.","25":"Все время, пока был жив Соломон, Резон старался причинить Израилю зло (и Хадад делал зло). Он был заклятым врагом Израиля. Он царствовал над арамеями.","26":"Некто Иеровоам, сын Невата, эфратянин из Цереды, сын вдовы по имени Церуа, был на службе у Соломона, а потом восстал против царя.","27":"Было это так. Когда Соломон строил Милло и заделывал брешь в стене Города Давидова,","28":"он обратил внимание на способного и исполнительного молодого человека (это был Иеровоам) и назначил его начальником надо всеми рабочими из племени Иосифа.","29":"Случилось в ту пору Иеровоаму выйти из Иерусалима, и повстречался ему на пути пророк Ахия из Силома. На нем был новый плащ, и были они одни в чистом поле.","30":"Ахия разорвал свой новый плащ на двенадцать кусков","31":"и сказал Иеровоаму: «Возьми себе десять кусков. Так говорит Господь, Бог Израиля: „Смотри, Я вырываю царство из рук Соломона и отдаю тебе десять племен.","32":"Но одно племя Я оставлю ему ради раба Моего Давида и ради Иерусалима – города, который Я избрал из всех владений племен Израилевых.","33":"Эти люди отвернулись от Меня, они стали поклоняться Астарте, богине сидонян, Кемошу, богу моавитян, и Милкому, богу аммонитян. Путями Моими они не ходят и того, что Мне угодно, не делают – не соблюдают ни законов, ни предписаний Моих. Не так поступал Соломонов отец Давид!","34":"Сейчас Я не буду отбирать у него царство: пока он жив, Я сохраняю за ним его власть – ради раба Моего Давида, которого Я избрал, и который соблюдал Мои заповеди и Мои законы.","35":"Но Я отниму царскую власть у его сына и вручу ее тебе: отдам тебе десять племен.","36":"Его сыну Я оставлю одно племя, чтобы светильник раба Моего Давида всегда горел пред лицом Моим в Иерусалиме, городе, который Я избрал, чтобы там обитало имя Мое.","37":"А тебя Я сделаю царем и подчиню тебе все, что ты пожелаешь, – ты будешь царем Израиля.","38":"Если ты будешь повиноваться всем Моим повелениям и будешь ходить путями, которые Я заповедал, и делать то, что Мне угодно, если будешь строго соблюдать и исполнять законы и повеления Мои, как соблюдал их раб Мой Давид, то Я буду с тобой и сделаю власть твоего рода неколебимой, как власть дома Давидова. Отдавая в твои руки Израиль,","39":"Я унижу Давидов дом – но не навсегда!\"»","40":"Соломон попытался убить Иеровоама, но тот бежал в Египет к египетскому царю Шешонку. В Египте он находился до смерти Соломона.","41":"А прочее о Соломоне, его деяниях и мудрости написано в «Летописи Соломоновой».","42":"Сорок лет правил Соломон в Иерусалиме, царствуя надо всем Израилем.","43":"Соломон почил с предками и был похоронен в Городе Давидовом. Царем после него стал Рехавам, его сын."},"12":{"1":"Рехавам отправился в Шехем: там должны были собраться все израильтяне, чтобы провозгласить его царем.","2":"Об этом узнал Иеровоам, сын Невата. Иеровоам был в Египте – он бежал туда от царя Соломона и жил там.","3":"Но за ним послали и позвали его. Иеровоам пришел туда вместе со всей общиной Израиля, и они сказали Рехаваму:","4":"«Твой отец придавил нас тяжким ярмом. Сделай нашу работу полегче, облегчи ярмо, что наложил на нас твой отец, – и мы будем служить тебе». –","5":"«Сейчас ступайте, – отвечал Рехавам, – приходите на третий день». Они разошлись.","6":"Царь Рехавам стал советоваться со старыми придворными, которые окружали его отца Соломона, пока тот был жив: «Что посоветуете, – спросил он их, – какой ответ дать народу?»","7":"Старики сказали: «Если ты этот день побудешь рабом народа, подчинишься ему и скажешь доброе слово – эти люди будут тебе рабами всю жизнь».","8":"Но Рехавам не внял совету стариков и стал советоваться с молодыми придворными, со своими ровесниками, которые его окружали.","9":"«Что посоветуете, – спросил он их, – какой ответ дать народу? Они меня просят: „Облегчи ярмо, что наложил на нас твой отец\"».","10":"Молодые придворные, его ровесники, сказали: «Вот что ответь народу. Они говорят: „Твой отец наложил на нас тяжкое ярмо, облегчи его\". А ты им так ответь: „Да мой мизинец потолще отцовской ляжки!","11":"Ярмо отца было для вас тяжелым? Мое будет еще тяжелее. Отец порол вас плетьми? Я буду бить вас кнутами\"».","12":"Иеровоам и все израильтяне пришли к Рехаваму на третий день (ведь царь так и велел им: «приходите на третий день»).","13":"Но царь говорил с ними сурово; не послушался он совета стариков","14":"и отвечал народу так, как советовали молодые: «Ярмо отца было для вас тяжелым? Мое будет еще тяжелее. Отец порол вас плетьми? Я буду бить вас кнутами».","15":"Не послушался царь народа: такова уж была воля Господа, чтобы исполнилось слово, которое Господь возвестил Иеровоаму, сыну Невата, через Ахию из Силома.","16":"Увидели израильтяне, что царь их не послушал, и сказали ему: «Кто нам теперь Давид? Нет нам дела до сына Иессеева! Расходись по домам, Израиль! Займись собственным домом, Давид!» И разошлись израильтяне по домам.","17":"А над сынами Израилевыми, живущими в Иудее, стал царствовать Рехавам.","18":"Царь Рехавам послал к израильтянам Адонирама, надзирателя за трудовой повинностью, но израильтяне насмерть забросали его камнями. Сам царь Рехавам еле успел взойти на колесницу, чтобы бежать в Иерусалим.","19":"С тех пор отпал Израиль от дома Давида.","20":"…Узнав, что Иеровоам вернулся, все израильтяне послали за ним, пригласили на народное собрание и провозгласили царем всего Израиля. Только племя Иуды осталось за домом Давидовым.","21":"Когда Рехавам пришел в Иерусалим, он собрал всех иудеев и все племя Вениамина – сто восемьдесят тысяч лучших воинов. Они должны были идти войной на Израиль и вернуть Рехаваму, сыну Соломонову, царскую власть.","22":"Тогда Шемае, человеку Божьему, было слово Господа:","23":"«Скажи Рехаваму, сыну Соломона, царю Иудеи, скажи всем иудеям и вениамитянам и прочему народу:","24":"„Так говорит Господь: не идите воевать с вашими братьями израильтянами, а лучше расходитесь по домам. Что случилось – то случилось по Моей воле!\"» Услышали они слово Господа, и покорившись слову Господа, вернулись.","25":"Иеровоам отстроил город Шехем, что на Ефремовых горах, и обосновался в нем. Потом он распространил свою власть дальше и отстроил город Пенуэл.","26":"И подумал Иеровоам: «Царство еще может вернуться к дому Давида!","27":"Если народ будет ходить в Иерусалим, чтобы приносить там жертвы в Храме Господа, то сердце этих людей вновь обратится к их господину – к Рехаваму, царю Иудеи. Они убьют меня и вернутся под власть Рехавама, царя Иудеи».","28":"Посоветовался царь – и сделал двух золотых тельцов и сказал своим подданным: «Не нужно вам больше ходить в Иерусалим! Вот, израильтяне, ваши боги, которые вывели вас из Египта!»","29":"Одного тельца он поставил в Бет – Эле, другого – в Дане.","30":"Так было положено начало греху. Одного из этих тельцов процессия народа сопровождала до самого Дана!","31":"Иеровоам построил храмы – капища и стал назначать священниками не левитов, а случайных людей.","32":"На пятнадцатый день восьмого месяца Иеровоам устроил праздник, подобный тому, какой бывает в Иудее. Он сам поднимается к жертвеннику (такой обычай завел он в Бет – Эле, принося жертвы тельцам, которых там поставил, – а служить в Бет – Эле назначил священников с капищ, которые сам же и построил).","33":"В пятнадцатый день восьмого месяца (месяц, который он выбрал по собственному произволу, чтобы учредить праздник для израильтян) поднимается он к жертвеннику в Бет – Эле (который сам же и воздвиг). Поднимается он к жертвеннику, чтобы вознести жертвенный дым…"},"13":{"1":"…И тут появился человек Божий: он пришел в Бет – Эль из Иудеи по слову Господа. Иеровоам уже стоял у жертвенника, чтобы сжечь жертву,","2":"и тут человек Божий прокричал, обращая к жертвеннику слово Господа: «Жертвенник! Жертвенник! Так говорит Господь: родится человек в роду потомков Давида, его имя будет Иосия. И прямо на тебе, жертвенник, он заколет священников с капищ – тех самых священников, что приносили на тебе жертвы! И человеческие кости сожгут на тебе!»","3":"И тут же он подтвердил свои слова знамением. Он сказал: «Вот знамение того, что это говорил Господь: жертвенник расколется, и зола с него просыплется на землю».","4":"Когда царь Иеровоам услышал, что возвестил человек Божий бет – эльскому жертвеннику, то он протянул руку и приказал: «Взять его!» Но рука царя оцепенела, лишь только он протянул ее, и не мог он согнуть ее обратно.","5":"А жертвенник раскололся, и зола просыпалась с жертвенника на землю: сбылось знамение, которое возвестил человек Божий по слову Господа.","6":"Тогда царь попросил человека Божьего: «Помолись обо мне Господу, твоему Богу, пусть Он смилуется и даст мне руку согнуть». Помолился человек Божий Господу, и рука царя стала сгибаться, стала такой же, как прежде.","7":"Царь сказал человеку Божьему: «Зайди ко мне, поешь со мной, я одарю тебя!»","8":"Но тот ответил: «Даже если дашь мне полцарства, не зайду к тебе! Ни хлеба есть, ни воды пить я здесь не буду.","9":"Ибо так велит мне слово Господа: „Хлеба не ешь; воды не пей; дорогой, по которой пришел, не возвращайся\"».","10":"И ушел он обратно по другой дороге – не по той, по которой пришел в Бет – Эль.","11":"А в Бет – Эле жил один старый пророк. Его сыновья пришли и рассказали ему все, что в тот день человек Божий сделал в Бет – Эле и что говорил он царю. Все, что случилось там, сыновья рассказали отцу.","12":"«По какой дороге он ушел?» – спросил пророк у своих сыновей. Сыновья показали ему дорогу, по которой ушел человек Божий, приходивший из Иудеи.","13":"«Оседлайте осла для меня!» – велел пророк сыновьям. Они оседлали для него осла. Пророк сел на него,","14":"поехал за человеком Божьим и нашел его сидящим под дубом. «Не ты ли человек Божий, что пришел из Иудеи?» – спросил его пророк. «Я», – ответил тот.","15":"«Идем, – говорит, – поешь со мной!»","16":"Человек Божий ответил: «Не могу ни вернуться с тобой, ни зайти к тебе. Ни хлеба у тебя есть не стану, ни воды здесь не буду пить.","17":"Слово Господа велит мне: „Хлеба не ешь и воды не пей и дорогой, по которой ты пришел, не возвращайся\"».","18":"Но тот сказал: «Я тоже пророк, как и ты. Ангел принес мне слово Господа: „Верни его, пусть зайдет к тебе домой, поест и выпьет воды\"». Солгал он!","19":"А человек Божий вернулся, поел у него хлеба, воды попил.","20":"И вот, когда сидели они за столом, пророку, который вернул человека Божьего с дороги, было слово Господа.","21":"И он закричал человеку Божьему, пришедшему из Иудеи: «Так говорит Господь: за то, что ты ослушался слова Господнего и не исполнил повеления, которое дал тебе Господь Бог,","22":"вернулся, стал есть и пить в том месте, о котором тебе было сказано: „Хлеба не ешь и воды не пей\", – за это не будет твой труп погребен в твоей родовой усыпальнице».","23":"Когда человек Божий поел и попил, пророк, что вернул его с дороги, оседлал для него осла,","24":"и человек Божий снова пустился в путь. По дороге на него напал лев и растерзал его. Труп остался лежать на дороге, – а рядом стоял осел, и лев тоже остался стоять рядом с трупом.","25":"Мимо шли какие-то люди и видят: лежит на дороге труп, а рядом с трупом стоит лев. Они пришли и рассказали об этом в селении, где жил тот старый пророк.","26":"Когда пророк, который вернул человека Божьего с дороги, услышал о случившемся, он сказал: «Это человек Божий, ослушавшийся веления Господнего. Господь отдал его льву, и тот растерзал его – исполнилось возвещенное ему слово Господа».","27":"И пророк сказал сыновьям: «Оседлайте мне осла!» Оседлали ему осла.","28":"Он поехал и увидел: на дороге лежит труп, рядом стоят лев и осел – лев не тронул ни труп, ни осла.","29":"Пророк поднял тело человека Божьего, положил на осла и отвез в свое селение, чтобы оплакать и похоронить.","30":"Положил его в своей гробнице и оплакивал его: «О брат мой!»","31":"Похоронив его, пророк сказал сыновьям: «Когда умру, похороните меня в гробнице, где похоронен человек Божий. Рядом с его костями пусть лежат мои кости.","32":"Сбудется то, что он по слову Господа изрек о жертвеннике в Бет – Эле и обо всех храмах – капищах в городах Самарии!»","33":"Но и после этого не свернул Иеровоам со своего злого пути. Он продолжал делать священниками капищ кого попало: кто хотел стать священником капища, того он и посвящал в священники.","34":"Этот грех тяготел над всем домом Иеровоама, за это дом Иеровоама был истреблен и сметен с лица земли."},"14":{"1":"В ту пору заболел Авия, сын Иеровоама.","2":"Иеровоам сказал своей жене: «Переоденься, чтобы никто не догадался, что ты жена Иеровоама, и иди в Силом. Там живет пророк Ахия . Это он предсказал, что я стану царем!","3":"Возьми с собой десять хлебов, баранки и бутыль меду и иди к нему: он скажет тебе, что будет с сыном».","4":"Так и сделала жена Иеровоама: отправилась в Силом, пришла к дому Ахии. Ахия тогда ничего уже не видел – его глаза от старости ослепли.","5":"Но Господь предупредил Ахию: «Сейчас придет жена Иеровоама вопросить тебя о своем больном сыне» – и сказал, что ей нужно будет ответить. И вот, едва она подошла, притворяясь, будто это не она,","6":"едва услышал Ахия звук ее шагов за дверью, как сказал: «Заходи, жена Иеровоама! Зачем притворяешься, будто это не ты? Дурные вести у меня для тебя.","7":"Пойди, скажи Иеровоаму: „Так говорит Господь, Бог Израиля: Я возвысил тебя, сделал правителем Израиля, Моего народа,","8":"вырвал царскую власть из рук рода Давида – и отдал тебе. Но совсем не похож ты оказался на Давида, раба Моего, который исполнял Мои повеления и был Мне предан всем сердцем и делал лишь то, что Мне было угодно!","9":"Ты всех своих предшественников превзошел во зле: ты завел себе других богов, завел истуканов – все то, что оскорбляет Меня, – а Меня отверг!","10":"За это Я предам весь род Иеровоама гибели! Я истреблю в Израиле всех мужчин из рода Иеровоама, от мала до велика! Я уничтожу весь род Иеровоама подчистую – как навоз сжигают!","11":"В городе трупы Иеровоамовой родни станут добычей собак, за городом – пищей стервятников\". Так сказал Господь!","12":"А ты ступай домой. Как только ты войдешь в город, ребенок умрет.","13":"Весь Израиль будет его оплакивать. Его похоронят – и он будет единственным из рода Иеровоама, кто удостоится погребения, так как он единственный из рода Иеровоама, в ком Господь, Бог Израиля, увидел что-то доброе.","14":"Господь поставит над Израилем царя, который истребит весь род Иеровоама. Да!","15":"Господь нанесет Израилю такой удар, что будет Израиль качаться, как тростник над водой. Выкинет Господь израильтян из доброй земли, которую дал их предкам, и рассеет их по ту сторону Евфрата, за то что они понаставили себе Ашер, оскорбили Господа.","16":"Оставит Господь Израиль за грехи Иеровоама и за то, что он весь Израиль ввел в грех».","17":"Жена Иеровоама пошла обратно, пришла в Тирцу и едва переступила порог дома, как ребенок умер.","18":"Его похоронили, и весь Израиль оплакивал его – исполнилось слово Господа, возвещенное рабом Его пророком Ахией.","19":"А прочее об Иеровоаме, о войнах, которые он вел, и о его царствовании написано в «Летописях царей Израиля».","20":"Царствовал Иеровоам двадцать два года. Он почил с предками; царем после него стал его сын Надав.","21":"В Иудее воцарился Рехавам, сын Соломона. Сорок один год был Рехаваму, когда он стал царем. Семнадцать лет он царствовал в Иерусалиме – городе, который Господь выбрал из всех владений племен Израилевых, чтобы там обитало имя Его. Матерью Рехавама была Наама - аммонитянка.","22":"А иудеи творили дела, ненавистные Господу, и оскорбляли Его своими грехами еще больше, чем их предки.","23":"На каждом высоком холме, под каждым деревом ветвистым они воздвигали себе капища, священные камни и Ашеры.","24":"Появились и «посвященные». Иудеи повторяли все гнусности тех народов, чьи земли Господь отдал израильтянам.","25":"В пятый год царствования Рехавама было нашествие Шешонка, царя Египта, на Иерусалим.","26":"Он забрал и сокровища Храма Господа, и сокровища царского дворца – все, что там было, он забрал. Взял он и все золотые щиты, сделанные Соломоном.","27":"Вместо них царь Рехавам сделал медные щиты и вверил их начальникам стражи, охранявшей вход во дворец.","28":"Всякий раз, как царь шествовал в Храм Господа, стражники несли эти щиты, а после складывали их в комнате стражников.","29":"Прочее о Рехаваме и его деяниях написано в «Летописях царей Иудеи».","30":"Между Рехавамом и Иеровоамом постоянно была война.","31":"Рехавам почил с предками и был похоронен вместе с предками в Городе Давидовом. Его мать – Наамааммонитянка. Царем после него стал его сын Авиям."},"15":{"1":"В восемнадцатый год царствования Иеровоама, сына Невата, царем Иудеи стал Авиям.","2":"Три года он царствовал в Иерусалиме. Его мать – Мааха, дочь Авессалома.","3":"Он шел греховным путем своего отца и не был так, всем сердцем, предан Господу, своему Богу, как был предан его прародитель Давид.","4":"И все-таки ради Давида Господь, его Бог, не дал угаснуть его светильнику в Иерусалиме: Господь возвел его сына на отцовский престол и поддержал Иерусалим.","5":"Ведь дела Давида были угодны Господу, и он следовал повелениям Господа до конца своих дней (кроме одного – единственного случая с Урией – хеттом).","6":"Прочее об Авияме и его деяниях написано в «Летописях царей Иудеи». Между Авиямом и Иеровоамом была война.","8":"Авиям почил с предками и был похоронен в Городе Давидовом; царем после него стал его сын Аса .","9":"В двадцатый год царствования Иеровоама, сына Невата, царя Израиля, царем Иудеи стал Аса.","10":"Сорок один год он царствовал в Иерусалиме. Его мать – Мааха, дочь Авессалома.","11":"Аса, подобно его прародителю Давиду, творил дела, угодные Господу.","12":"При нем не стало больше «посвященных» в стране; он уничтожил все истуканы, поставленные его предками.","13":"Даже свою мать Мааху он лишил звания царицы за то, что она велела изготовить омерзительную Ашеру. Аса велел срубить эту мерзость и сжег у ручья Кедрон.","14":"Капища по – прежнему стояли; и все же Аса до конца своих дней был всем сердцем предан Господу.","15":"Он поместил в Храм Господа дары, которые его отец и он сам посвятили Господу: серебро, золото и храмовую утварь.","16":"Между Асой и Башой, царем Израиля, постоянно была война.","17":"Баша, царь Израиля, начал войну с Иудеей и стал укреплять крепость Раму, чтобы никто не мог ни проехать во владения Асы, царя Иудеи, ни выехать оттуда.","18":"Тогда Аса взял все серебро и золото, какое оставалось в казне Храма Господа и в дворцовой казне, и отправил его, с послами, к Бен – Хададу, сыну Тавриммона, сына Хезиона, царю арамеев, правителю Дамаска.","19":"«Мы с тобой союзники, – говорил он Бен – Хададу, – союзниками были наши отцы. Это серебро и золото я посылаю тебе в дар. Расторгни союз с Башой, царем Израиля, чтобы он отступил от моих владений».","20":"Бен – Хадад согласился с предложением Асы и послал своих полководцев против Израиля. Он захватил города Ийон, Дан, Авел – Бет – Мааху, всю округу Кинрот и всю землю Неффалимову.","21":"Узнав об этом, Баша перестал укреплять Раму и обосновался в Тирце .","22":"Тогда царь Аса созвал всех иудеев без исключения, чтобы они унесли из Рамы камни и бревна, которые Баша использовал для строительства крепости. Из них царь Аса построил крепость Геву, что в земле Вениаминовой, а также крепость Мицпу .","23":"Прочее об Асе, его деяниях и доблести, о городах, которые он укрепил, написано в «Летописях царей Иудеи». В старости он страдал болезнью ног.","24":"Аса почил с предками и был похоронен вместе с предками в Городе Давидовом; царем после него стал его сын Иосафат.","25":"Надав, сын Иеровоама, стал царем Израиля во второй год царствования Асы, царя Иудеи. Он царствовал в Израиле два года.","26":"Он творил дела, ненавистные Господу, шел греховным путем своего отца, который весь Израиль ввел в грех.","27":"Баша, сын Ахии, из рода Иссахара, составил против него заговор и убил его под филистимским городом Гиббетоном (Надав и все израильтяне осаждали тогда Гиббетон).","28":"Баша убил Надава и стал вместо него царем в третий год царствования Асы, царя Иудеи.","29":"Став же царем, он перебил весь дом Иеровоама – никого из рода Иеровоама не оставил в живых, всех уничтожил. Исполнилось слово Господа, возвещенное рабом его Ахи – ей из Силома,","30":"пришло возмездие за грехи Иеровоама – и за то что он весь Израиль ввел в грех, оскорбил Господа, Бога Израиля.","31":"Прочее о Надаве и его деяниях написано в «Летописях царей Израиля».","32":"Между Асой и Башой, царем Израиля, постоянно была война.","33":"В третий год царствования Асы, царя Иудеи, Баша, сын Ахии, стал царем всего Израиля. Двадцать четыре года он царствовал в Тирце.","34":"Он творил дела, ненавистные Господу, шел греховным путем Иеровоама, который весь Израиль ввел в грех."},"16":{"1":"Было слово Господа к Иегу, сыну Ханани, – чтобы он возвестил царю Баше:","2":"«Я поднял тебя из праха, сделал правителем Израиля, Моего народа, а ты пошел путем Иеровоама. Ты вверг в грех Мой народ, Израиль, – и они оскорбили Меня своими грехами.","3":"3а это Я уничтожу подчистую все потомство Баши, весь его род! Та же участь постигнет его род, что и род Иеровоама, сына Невата.","4":"В городе трупы его родни станут добычей собак, за городом – пищей стервятников».","5":"Прочее о Баше, о его деяниях и доблести написано в «Летописях царей Израиля».","6":"Баша почил с предками и был похоронен в Тирце; царем после него стал его сын Эла .","7":"Но устами пророка Иегу, сына Ханани, Господь уже изрек приговор и Баше, и всему его роду – за то что Баша творил дела, ненавистные Господу и оскорблял Его своими делами, подобно царям из рода Иеровоама (и еще за то, что он истребил Иеровоамов род).","8":"В двадцать шестой год царствования Асы, царя Иудеи, царем Израиля стал Эла, сын Баши. Два года он царствовал в Тирце.","9":"Его приближенный Зимри, командовавший половиной колесничного войска, составил против него заговор. Царь пировал в Тирце, у Арцы, старшего над дворцом. Когда царь напился допьяна,","10":"Зимри вошел и убил его. Это было в двадцать седьмой год царствования Асы, царя Иудеи.","11":"Когда Зимри воцарился и занял царский престол, он перебил весь род Баши – не оставил ни одного мужчины; не пощадил ни родственников, ни друзей.","12":"Так исполнилось слово Господа про Башу, возвещенное через пророка Иегу: Зимри истребил весь род Баши","13":"за все грехи Баши и его сына Элы – за их грехи и за то что они весь Израиль ввергли в грех, оскорбляя Господа, Бога Израиля, своими пустыми божками.","14":"Прочее про Элу и его деяния написано в «Летописях царей Израиля».","15":"В двадцать седьмой год царствования Асы, царя Иудеи, царем Израиля стал Зимри. Семьдесят дней он царствовал в Тирце. Народ израильский в то время стоял лагерем под филистимским городом Гиббетоном.","16":"В тот же самый день, как стало известно, что Зимри составил заговор и убил царя, все израильское войско, что находилось в военном стане, провозгласило царем своего военачальника Омри .","17":"Омри отступил от Гиббетона, двинулся со всем израильским войском на Тирцу и осадил ее.","18":"Когда Зимри увидел, что город взят, он вошел во дворец, в царские покои, поджег дворец и погиб в огне.","19":"Так поплатился он за свои грехи, за то что творил дела, ненавистные Господу, и шел греховным путем Иеровоама, который весь Израиль ввел в грех.","20":"Прочее о Зимри и его заговоре написано в «Летописях царей Израиля».","21":"Тогда израильтяне разделились: половина народа была за Тивни, сына Гината, желая провозгласить его царем, а половина – за Омри.","22":"Те, что были за Омри, победили тех, что были за Тивни, сына Гината. Тивни умер, царем стал Омри.","23":"В тридцать первый год царствования Асы, царя Иудеи, царем Израиля стал Омри. Он царствовал двенадцать лет: шесть из них – в Тирце.","24":"Омри купил у Шемера за два таланта серебра Самарийскую гору и построил на ней город. Этот город, построенный им, назвали Самарией в честь Шемера, владельца горы.","25":"Омри творил дела, ненавистные Господу; он сделал еще больше зла, чем все, кто царствовал до него.","26":"Он шел греховным путем Иеровоама, сына Невата, который весь Израиль ввел в грех, оскорбляя Господа, Бога Израиля, своими пустыми божками.","27":"А прочее об Омри, о его деяниях и доблести написано в «Летописях царей Израиля».","28":"Омри почил с предками и был похоронен в Самарии; царем после него стал его сын Ахав.","29":"Ахав, сын Омри, стал царем Израиля в тридцать восьмой год царствования Асы, царя Иудеи. Двадцать два года Ахав, сын Омри, царствовал над Израилем в Самарии.","30":"Ахав, сын Омри, творил дела, ненавистные Господу, больше всех, кто царствовал до него.","31":"Мало ему было повторять грехи Иеровоама, сына Невата, – он еще взял в жены Иезавель, дочь Этбаала, царя сидонян, и стал служить Ваалу, стал поклоняться ему.","32":"Он воздвиг жертвенник для Ваала – построил в Самарии храм Ваала.","33":"Воздвиг он и Ашеру. Ахав оскорблял Господа, Бога Израилева, больше всех царей Израиля, что царствовали до него.","34":"При нем Хиэль из Бет – Эля отстроил Иерихон: жизнью старшего сына, Авирама, заплатил за основание города; жизнью младшего сына, Сегува, – за то, что навесил ворота – так исполнилось слово Господа, возвещенное Иисусом Навином."},"17":{"1":"Илия Тишбийский (из Тишбе Галаадского) сказал Ахаву: «Клянусь Господом, Богом Израиля, которому я служу: ни росы, ни дождя в эти годы не будет – разве что по моему повелению».","2":"И было Илие после этого слово Господа:","3":"«Уходи отсюда, иди на восток и скрывайся у ручья Керит, что к востоку от Иордана.","4":"Воду будешь пить из ручья, а кормить тебя Я велел воронам».","5":"Илия сделал, как сказал ему Господь, – пошел и поселился у ручья Керит, к востоку от Иордана.","6":"Каждое утро и каждый вечер вороны приносили ему хлеб и мясо, а воду он пил из ручья.","7":"Но время шло, и ручей высох, ведь по всей стране не было дождя.","8":"И было Илие слово Господа:","9":"«Иди и живи в сидонском городе Сарепте, там одной вдове Я велел кормить тебя».","10":"Илия отправился в Сарепту. Подходя к городским воротам, он увидел вдову, собиравшую хворост, подозвал ее и сказал: «Принеси мне попить немного воды в кувшине!»","11":"Она пошла за водой, но он снова подозвал ее и сказал: «Принеси мне ломоть хлеба!» –","12":"«Клянусь Господом, твоим Богом, – ответила она, – хлеба у меня нет ни кусочка. Все, что есть – горсть муки в кадушке и немного масла в кувшине. Вот подберу пару сучков, пойду испеку что-нибудь для себя и для сына, съедим это – и пора умирать…» –","13":"«Не бойся, – сказал ей Илия. – Сделай все так, как ты сказала, только сперва испеки и принеси мне маленькую лепешку. А себе и сыну после испечешь.","14":"Так говорит Господь, Бог Израиля: „Не закончится в кадушке мука, не иссякнет масло в кувшине, пока не пошлет Господь дождь на землю\"».","15":"Она пошла и сделала, как велел Илия. И с тех пор, день за днем, была еда и для нее, и для Илии, и для ее домашних.","16":"Не кончалась в кадушке мука, не иссякало масло в кувшине, как возвестил Господь через Илию.","17":"Через какое-то время у хозяйки заболел сын. Ему становилось все хуже и хуже. Когда он уже не дышал,","18":"она сказала Илие: «Что нужно тебе от меня, человек Божий? Ты пришел, чтобы обличить мои грехи? Принести смерть моему сыну?» –","19":"«Дайка мне своего сына», – сказал ей Илия. Он взял у нее ребенка, отнес его наверх, к себе в комнату, положил на свою кровать","20":"и воззвал к Господу: «О Господь, Бог мой! Неужели и этой вдове, у которой я нашел приют, Ты сделаешь зло и убьешь ее сына?»","21":"Трижды простирался он на теле ребенка и призывал Господа: «О Господь, Бог мой! Пусть жизнь вернется в тело этого ребенка!»","22":"Господь услышал Илию, и жизнь вернулась в тело ребенка. Он стал дышать.","23":"Илия взял ребенка, отнес его из своей комнаты вниз, отдал матери и сказал: «Смотри, твой сын жив». –","24":"«Теперь я знаю, что ты человек Божий, – сказала она Илие. – Поистине, в твоих устах слово Господа!»"},"18":{"1":"Время шло. На третий год было Илие слово Господа: «Иди, предстань перед Ахавом, и Я пошлю дождь на землю».","2":"И пошел Илия, чтобы предстать перед Ахавом. В Самарии свирепствовал голод.","3":"Ахав вызвал к себе Авдия, старшего во дворце. (Авдий по – настоящему чтил Господа:","4":"когда Иезавель истребляла пророков Господа, то Авдий спас сто пророков, спрятал их в пещерах, по пятьдесят человек в пещере, и доставлял им еду и питье.)","5":"«Надо обойти всю страну, все родники и ручьи, – 1сказал Ахав Авдию, – может, найдем травы, чтобы прокормить лошадей и мулов и не потерять весь скот».","6":"Поделили они страну – кто какую ее часть будет обходить – и Ахав пошел в одну сторону, а Авдий в другую.","7":"Идет Авдий – и тут навстречу ему Илия. Авдий узнал его, пал ниц и спросил: «Это ты, господин мой Илия?» –","8":"«Я, – ответил тот. – Ступай, скажи своему господину, что Илия здесь». –","9":"«Чем я провинился, – воскликнул Авдий, – что ты посылаешь меня, раба твоего, на смерть от руки Ахава?","10":"Клянусь Господом, твоим Богом, нет такой страны, нет такого царства, куда бы мой господин не посылал гонцов искать тебя. Везде отвечали: „Его тут нет\", а он еще заставлял отвечавших поклясться, что не видели тебя.","11":"И вдруг ты говоришь: „Пойди, скажи своему господину, что Илия здесь\".","12":"Я отойду от тебя, а дух Господа тебя подхватит, как ветер, и унесет, не знаю куда! Я приду, доложу Ахаву, а он тебя здесь не найдет и казнит меня. А ведь раб твой чтит Господа с юных лет!","13":"Разве не рассказывали тебе, господин мой, что когда Иезавель убивала пророков Господа, я спас сто пророков и спрятал их в пещерах, по пятьдесят человек в пещере, и доставлял им еду и питье?","14":"Зачем ты говоришь: „Пойди, скажи своему господину, что Илия здесь?\" Чтобы он казнил меня?» –","15":"«Клянусь Господом Саваофом, которому я служу, – ответил Илия. – Я сегодня же предстану перед царем».","16":"Тогда Авдий разыскал Ахава и передал ему слова Илии. Царь пошел Илие навстречу.","17":"Увидел его и сказал: «Это ты, проклятье Израиля?»","18":"И сказал Илия в ответ: «Проклятье Израиля – это не я, а ты и твой род! Это вы отвергли законы Господа и стали служить Ваалам.","19":"Разошли гонцов по всему Израилю и собери народ ко мне на гору Кармил. Пусть придут и четыреста пятьдесят пророков Ваала, и четыреста пророков Ашеры, которые кормятся за столом у Иезавели».","20":"Ахав разослал гонцов по всему Израилю и собрал пророков на горе Кармил.","21":"Илия стал перед народом и сказал: «Долго еще будете метаться туда – сюда? Если Господь – ваш Бог, то идите за Господом, если Ваал – то за Ваалом!» Народ молчал.","22":"Тогда Илия сказал народу: «Из пророков Господа один я остался, а пророков Ваала – четыреста пятьдесят человек.","23":"Пусть приведут нам сюда двух быков. Пророки Ваала могут выбрать себе любого из них – пусть приготовят мясо для жертвоприношения и положат на дрова, но огня не разводят. А я возьму другого быка и тоже приготовлю мясо для жертвоприношения и тоже положу на дрова, но огня не разведу.","24":"Вы призовите имя вашего бога, а я призову имя Господа. Какой бог в ответ ниспошлет огонь, тот и есть настоящий Бог». И ответил ему весь народ: «Пусть так и будет!»","25":"Илия сказал пророкам Ваала: «Выбирайте быка и готовьте все первыми, ведь вас больше. Давайте, призывайте имя вашего бога, только огня не разводите».","26":"Они взяли быка, приготовили мясо для жертвоприношения и стали призывать имя Ваала. С утра до полудня кричали они и звали: «Ваал, ответь нам!» Но в ответ – ничего. А они все скакали вокруг жертвенника, который они соорудили.","27":"Настал полдень. Илия стал потешаться над ними: «Кричите громче, если он бог! Может, он задумался? Может, по делам пошел? Может, в дороге? А может, заснул – так проснется?»","28":"Стали они громче кричать, стали, как у них принято, колоть себя мечами и копьями – кровь ручьями лилась по ним.","29":"Так неистовствовали они от полудня и до самого часа вечернего жертвоприношения, но в ответ – ничего.","30":"Тогда Илия обратился к народу: «Подойдите ко мне». Все подошли к нему. Илия стал восстанавливать разрушенный жертвенник Господа.","31":"Он взял двенадцать камней – по числу племен, что произошли от сыновей Иакова, которому Господь дал имя «Израиль», –","32":"и соорудил из этих камней жертвенник имени Господнему. Жертвенник он окружил бороздой, в которую могли бы вместиться две меры зерна.","33":"Потом разложил дрова, приготовил тушу быка для жертвоприношения, положил поверх дров","34":"и велел: «Наберите четыре кувшина воды и полейте на жертву и на дрова». Потом сказал: «Еще раз!» Полили во второй раз. Снова сказал: «Еще раз!» И полили в третий раз.","35":"Вода потекла вокруг жертвенника, наполнила борозду.","36":"Наступил час вечернего жертвоприношения. Тогда подошел пророк Илия к жертвеннику и сказал: «О Господь, Бог Авраама, Исаака и Израиля! Пусть уразумеют сегодня люди, что Ты – Бог Израиля, и что я – раб Твой, и что все это я сделал по Твоему велению!","37":"Ответь мне, Господь, ответь! Пусть уразумеют эти люди, что настоящий Бог – это Ты, Господь, и что сердца их в Твоей власти!»","38":"И ниспал огонь Господень и поглотил и жертву, и дрова, и камни, и землю вокруг, и воду из борозды.","39":"Когда люди это увидели, то пали ниц со словами: «Господь – наш Бог! Господь – наш Бог!»","40":"А Илия сказал им: «Хватайте пророков Ваала, пусть ни один не уйдет!» Пророков Ваала схватили, Илия отвел их к ручью Кишон и всех убил,","41":"а после сказал Ахаву: «Иди, ешь и пей. Уже слышен шум ливня!»","42":"Ахав ушел есть и пить. А Илия взошел на вершину Кармила, опустился на колени, склонил голову вниз, к коленям,","43":"и сказал слуге: «Ступай, посмотри на море». Тот пошел, посмотрел и сказал: «Ничего нет». – «Еще раз», – сказал Илия. Так повторилось семь раз.","44":"На седьмой раз слуга сказал: «Тучка, с ладонь величиною, показалась над морем». Илия велел ему: «Ступай, скажи Ахаву: „Запрягай колесницу и отправляйся домой, а не то попадешь под ливень, проехать не сможешь!\"»","45":"Тем временем небо стало темнеть. Ветер нагнал тучи, пошел проливной дождь. Ахав взошел на колесницу и поехал в Изреель.","46":"Сила Господа была с Илией – и, подоткнув подол одежды, он бежал перед колесницей Ахава до самого Изрееля."},"19":{"1":"Ахав рассказал Иезавели, что сделал Илия и как он перебил всех пророков.","2":"Иезавель велела передать Илие: «Пусть так-то и так-то покарают меня боги, если завтра я не сделаю с тобой то же самое!»","3":"Илия испугался за свою жизнь и ушел в Беэр – Шеву иудейскую. Там он оставил своего слугу,","4":"а сам удалился в пустыню на один день пути, сел под ракитой и стал молить Господа о смерти: «Довольно с меня, Господь! Возьми мою жизнь – чем я лучше моих предков?»","5":"Он лег и уснул под ракитой. И видит: ангел коснулся его и говорит ему: «Встань, поешь».","6":"Смотрит – у него в изголовье лепешка, испеченная на углях, и кувшин с водою. Он поел, попил, лег опять –","7":"и снова посланец Господа коснулся его и сказал: «Встань, поешь – неблизкий путь тебе предстоит».","8":"Он встал, поел и попил. Подкрепившись этой пищей, шел сорок дней и сорок ночей, пока не пришел к Божьей горе, к Хориву.","9":"Там Илия заночевал в пещере. И вот – слышит он слово Господа: «Зачем ты здесь, Илия?»","10":"Он ответил: «Я в ярости от оскорблений, нанесенных Господу, Богу Саваофу! Забыли израильтяне про договор с Тобой, жертвенники Твои разрушили, пророков Твоих убили. Один я остался, но и меня они хотят убить».","11":"Господь сказал: «Выйди, предстань на горе перед Господом». И увидел Илия, как мимо идет Господь. Перед Господом – мощный могучий ветер, дробящий горы, крушащий скалы; но Господь не в ветре. Следом за ветром – землетрясение, но Господь не в землетрясении.","12":"Следом за землетрясением – огонь, но Господь не в огне. А следом за огнем – тонкий звук тишины…","13":"Услышал это Илия и закрыл лицо мантией, вышел и стал у входа в пещеру. И был ему голос: «Зачем ты здесь, Илия?»","14":"Он ответил: «Я в ярости от оскорблений, нанесенных Господу, Богу Саваофу! Забыли израильтяне про договор с Тобой, Твои жертвенники разрушили, перебили Твоих пророков. Один я остался, но и меня они хотят убить».","15":"Господь сказал ему: «Отправляйся снова в путь. Иди в Дамасскую пустыню и своим помазанием возведи Хазаэла в цари арамеев,","16":"Иегу, сына Нимши , – в цари Израиля, а Елисея, сына Шафата, из Авел – Мехолы, – в пророки, он будет твоим преемником.","17":"Кто уйдет от меча Хазаэла – того убьет Иегу, кто уйдет от меча Иегу – того убьет Елисей.","18":"Я оставлю в Израиле семь тысяч человек – тех, кто не преклонял колен перед Ваалом и не целовал его устами».","19":"Илия отправился в путь и ему повстречался Елисей, сын Шафата. Он пахал свое поле на двенадцати воловьих упряжках, а сам шел за последней, двенадцатой упряжкой. Поравнявшись с ним, Илия набросил на него свою мантию –","20":"Елисей оставил волов и побежал вслед за Илией. «Я попрощаюсь с отцом и матерью и пойду за тобой», – сказал он Илие. «Сходи, сходи, – отвечал Илия. – Разве я тебе мешаю?»","21":"Елисей вернулся, взял своих двух волов, зарезал их и сварил мясо, пустив ярмо на дрова. Он устроил трапезу для всех, кто там был, а потом пошел за Илией и стал его слугой."},"20":{"1":"Бен – Хадад, царь арамеев, собрал все свое войско – и еще тридцать два царя присоединились к нему – собрал конницу, колесницы и двинулся на Самарию. Он окружил и осадил ее,","2":"а к Ахаву, царю Израиля, отправил послов","3":"с такими словами: «Так говорит Бен – Хадад: твое серебро и золото принадлежат мне, лучшие из твоих женщин и детей – все мои».","4":"Отвечал царь Израиля: «Все, как ты сказал, мой царь и господин. И сам я твой, и все, что есть у меня, твое».","5":"Снова явились послы и сказали: «Так говорит Бен – Хадад: я приказал тебе, чтобы ты отдал мне свое серебро и золото, женщин и детей.","6":"Поэтому завтра, в это же время, я пришлю к тебе своих людей, чтоб они сами обыскали твой дворец и дворцы твоих вельмож и сами забрали у тебя все, чем ты дорожишь».","7":"Царь Израиля созвал всех старейшин своей страны и сказал: «Смотрите, какую беду он нам готовит… Когда он просто требовал дать ему женщин и детей, серебро и золото, я же ведь не отказался!»","8":"И сказали ему все старейшины и весь народ: «Не слушайся и не соглашайся».","9":"Царь ответил послам Бен – Хадада: «Передайте моему царю и господину: прежнее твое требование я, раб твой, готов исполнить. Но того, что ты требуешь теперь, – не могу». Послы передали это Бен – Хададу.","10":"Бен – Хадад ответил: «Пусть так-то и так-то покарают меня боги, если пыли, которую я здесь оставлю от Самарии, хватит, чтобы наполнить пригоршни моих воинов!»","11":"Царь Израиля сказал: «Передайте ему: хвались не когда надеваешь доспехи, а когда снимаешь!»","12":"Когда эти слова передали Бен – Хададу (он пировал с другими царями у себя в стане), он велел своему войску приготовиться к бою. Войско выстроилось напротив города.","13":"Тогда подошел к Ахаву, царю Израиля, один пророк и сказал: «Так говорит Господь: видишь эти несметные полчища? Сегодня Я предам их в твои руки, и ты поймешь, что Я – Господь». –","14":"«Через кого Господь это сделает?» – спросил Ахав. Пророк ответил: «Так говорит Господь: это будут бойцы областных наместников». – «Кто должен начать битву?» – спросил царь. Пророк ответил: «Ты».","15":"Царь приказал, чтобы собрались бойцы областных наместников; их оказалось двести тридцать два человека. Потом приказал собрать все израильское войско; в нем оказалось семь тысяч человек.","16":"В полдень все они выступили из города. А Бен – Хадад продолжал пировать у себя в стане с тридцатью двумя царями, своими союзниками, и напился допьяна.","17":"Первыми из города вышли бойцы областных наместников. Бен – Хадад выслал дозорных, и те сообщили ему: «Какие-то люди вышли из Самарии».","18":"Он ответил: «Если идут просить о мире – тогда хватайте их живьем. Если сражаться идут – тогда живьем хватайте!»","19":"Израильтяне выступили из города в таком порядке: впереди – бойцы областных наместников, следом за ними – остальное войско.","20":"Завязалась битва, арамеи побежали, израильтяне бросились их преследовать. Царь арамеев пустился в бегство верхом, с конными отрядами, –","21":"и тут вступил в бой царь Израиля, разгромил и конницу, и колесницы арамеев. Страшное поражение нанес он арамеям.","22":"А пророк подошел к царю Израиля и сказал: «Иди, собирайся с силами и думай, как тебе быть дальше, потому что на следующий год царь арамеев снова пойдет на тебя войною».","23":"Приближенные арамейского царя сказали ему: «Их бог – горный бог, потому-то они и одолели нас. Но если бы мы сражались с ними на равнине – точно победили бы!","24":"И еще совет: смести царей с их престолов, а вместо них поставь своих наместников.","25":"Набери себе новых воинов – столько же, сколько у тебя пало в битве, и конницы столько же, и колесниц столько же, и сразимся с ними на равнине – тогда точно одолеем их!» Царь послушался совета: как они сказали ему, так он и сделал.","26":"И вот на следующий год Бен – Хадад, собрав арамейское войско, подступил к Афеку, чтобы сразиться с израильтянами.","27":"Израильтяне тоже собрали войско, взяли с собой припасы и вышли навстречу арамеям. Они стали лагерем напротив арамеев – и по сравнению с арамеями, заполнившими собой всю землю, казались двумя маленькими гуртами коз.","28":"Но подошел к царю Израиля человек Божий и сказал: «Так говорит Господь. За то, что арамеи решили: „Господь – бог гор, а не бог долин\", Я предам эти полчища в твои руки. И вы узнаете, что Я – Господь».","29":"Семь дней войска стояли друг против друга. На седьмой день завязалось сражение, и израильтяне разгромили арамеев – перебили в один день сто тысяч пехотинцев.","30":"Уцелевшие побежали в Афек, в крепость, но крепостная стена обрушилась и задавила двадцать семь тысяч уцелевших воинов. А сам Бен – Хадад, бежав, укрылся в крепости и забился в самый дальний угол.","31":"Приближенные сказали ему: «Мы слышали о царях Израиля, что они – цари, верные своему слову. Обвяжем бедра дерюгой, наденем на шею веревку и выйдем к царю Израиля – может быть, он пощадит тебя?»","32":"Они обвязали бедра дерюгой, надели веревку на шею, вышли к царю Израиля и сказали: «Раб твой Бен – Хадад говорит: пощади меня!» – «Так он жив? – воскликнул царь. – Брат мой жив?»","33":"Те сочли это добрым предзнаменованием и сразу подхватили: «Бен – Хадад – брат твой!» – «Ступайте, приведите его!» – велел царь. Бен – Хадад вышел к нему. Царь Израиля посадил его в свою колесницу.","34":"Бен – Хадад сказал: «Я возвращаю города, которые отобрал мой отец у твоего отца. И пусть будет у тебя в Дамаске свой торговый квартал, как мой отец сделал в Самарии. Мы заключим договор и простимся». Они заключили договор и простились.","35":"Тогда, по велению Господа, один пророк из пророческого братства сказал другому: «Бей меня!» Но тот его бить не стал,","36":"и тогда он сказал: «Ты ослушался Господа. За это, как только мы расстанемся, тебя растерзает лев». Когда они расстались, того пророка встретил лев и растерзал его.","37":"А первый пророк обратился к другому человеку: «Ударь меня!» И тот избил его до полусмерти.","38":"Пошел пророк и стал в ожидании царя у дороги, обвязав голову повязкой.","39":"А когда царь проходил мимо, обратился к нему с мольбой: «Я, раб твой, был на поле битвы. Там ко мне подошел один человек, подвел пленника и сказал: „Постереги. Если я приду и его не найду, ты сам окажешься на его месте – или заплатишь мне талант серебра\".","40":"А мне нужно было сделать одно, другое – и тут пленный пропал…» Царь Израиля ответил ему: «Придется тебе поплатиться за это. А как – сам только что сказал».","41":"Тот немедленно сорвал с головы повязку, и царь Израиля понял, что перед ним один из пророков.","42":"И сказал пророк: «Так говорит Господь: ты упустил человека, которого Я предал заклятью! Теперь на его месте окажешься ты сам, а на месте его народа – твой народ».","43":"Царь Израиля вернулся домой, в Самарию, мрачный и злой."},"21":{"1":"А немного спустя случилось вот что. В Изрееле, прямо рядом с дворцом Ахава, царя Самарии, у Навота из Изрееля был виноградник.","2":"«Отдай мне свой виноградник, – сказал Ахав Навоту. – Он рядом с моим дворцом, и я устрою там сад, а тебе дам взамен виноградник еще лучше. Или, если хочешь, заплачу, сколько он стоит».","3":"Навот ответил: «Сохрани меня Господь! Я не отдам тебе землю моих предков!»","4":"Из-за этих слов Навота: «Не отдам тебе землю моих предков», Ахав вернулся домой мрачный и злой, лег на постель, ни на кого не хотел смотреть, даже есть не стал.","5":"К нему пришла его жена Иезавель. «Что с тобой? Почему ты мрачен? – спросила она. – Почему не хочешь есть?» –","6":"«Я говорил с Навотом из Изрееля, – ответил ей царь, – сказал ему: „Отдай мне свой виноградник, я тебе заплачу или, если хочешь, дам другой виноградник, взамен\": Но он ответил: „Не отдам тебе моего виноградника\"». –","7":"«Какой же ты после этого царь Израиля? – сказала ему его жена Иезавель. – Вставай, ешь, веселись! А уж я добуду тебе виноградник Навота из Изрееля».","8":"Она написала от имени Ахава письма, запечатала их его печатью и послала эти письма старейшинам и знатным людям того города, где жил Навот.","9":"А в письмах велела: «Объявите пост. Посадите Навота на видное место, перед народом,","10":"а напротив посадите каких-нибудь двух негодяев, чтобы засвидетельствовали ему в лицо: „Ты хулил Бога и царя\". После этого берите Навота, уведите его и забросайте камнями насмерть».","11":"Жители города, старейшины и знатные люди, сделали все, как им велела Иезавель, как было написано в присланных ею письмах.","12":"Они объявили пост, посадили Навота на видное место, перед народом, а","13":"напротив него пришли и сели два негодяя. Эти негодяи засвидетельствовали перед всем народом: «Навот хулил Бога и царя». Навота вывели за город и забросали камнями насмерть.","14":"Потом доложили Иезавели: «Навота забросали камнями. Он мертв».","15":"Иезавель, узнав о казни Навота, сказала Ахаву: «Иди и забирай себе виноградник того самого Навота из Изрееля, который не хотел продать тебе этот виноградник за деньги. Навота нет. Он мертв».","16":"Ахав, узнав, что Навот из Изрееля мертв, сам отправился в виноградник, чтобы объявить его своей собственностью.","17":"И тогда Господь сказал Илие Тишбийскому:","18":"«Иди навстречу Ахаву, царю Израильскому, правящему в Самарии. Он сейчас в винограднике Навота, пришел туда, чтоб объявить его своей собственностью.","19":"А ты скажи ему: „Так говорит Господь: убил, а теперь получаешь наследство?\" Скажи ему: „Так говорит Господь: на том самом месте, где псы лизали кровь Навота, они будут лизать и твою собственную кровь!\"»","20":"«Отыскал ты меня, враг мой!» – сказал Ахав Илие. «Отыскал, – ответил Илия. – За то, что ты погряз в делах, ненавистных Господу,","21":"Я обрекаю тебя на гибель; Я подчистую уничтожу все потомство твое! Я истреблю всех мужчин из рода Ахава, от мала до велика.","22":"За оскорбления, которые ты Мне нанес, за то что весь Израиль ты повел по пути греха, Я сделаю с твоим родом то же самое, что с родом Иеровоама, сына Невата, и с родом Баши, сына Ахии.","23":"А об Иезавели так говорит Господь: на поле близ Изрееля собаки сожрут Иезавель!","24":"В городе трупы Ахавовой родни станут добычей собак, за городом – пищей стервятников!»","25":"(Никто никогда не предавался делам, ненавистным Господу, до такой степени, как Ахав, – а подстрекала его к тому жена, Иезавель.","26":"Какие гнусности он творил! Он поклонялся идолам, он подражал тем самым амореям, которых Господь прогнал, чтобы дать место Израилю.)","27":"Но когда Ахав услышал эти слова, он разодрал одежды в знак скорби, оделся в дерюгу, стал поститься, спал, не снимая дерюги, ходил тихонько…","28":"И было слово Господа Илие Тишбийскому:","29":"«Смотри, каким смирным стал Ахав передо Мной! За это Я не наведу на него беды, пока он жив. Зато в дни его сына Я наведу беду на весь род Ахава!»"},"22":{"1":"Три года не было войны между арамеями и Израилем.","2":"На третий год, когда Иосафат, царь Иудеи, пришел к царю Израиля,","3":"царь Израиля сказал своим вельможам: «Вы ведь знаете, что Рамот Галаадский – наш. А мы теряем время, вместо того, чтобы отобрать его у царя арамеев!»","4":"И он спросил Иосафата: «Пойдешь со мной войною на Рамот Галаадский?» Иосафат ответил царю Израиля: «Куда ты, туда и я. Мое войско идет за твоим войском, мои кони за твоими конями».","5":"И еще сказал Иосафат царю Израиля: «Сперва вопросим Господа».","6":"Царь Израиля собрал пророков, человек четыреста, и спрашивает их: «Идти ли мне войной на Рамот Галаадский или не ходить?» – «Иди, – отвечали они, – Господь предаст его в руки царя!»","7":"Иосафат спросил: «А нет ли еще какого-нибудь пророка Господнего, через которого мы могли бы вопросить Господа?»","8":"Царь Израиля ответил Иосафату: «Есть еще один человек, через которого можно вопросить Господа. Но не люблю я его: он никогда не пророчит мне ничего хорошего, всегда одни беды. Это Михей, сын Имлы». – «Не надо так говорить», – возразил Иосафат.","9":"Тогда царь Израиля подозвал одного евнуха и сказал: «Скорее приведи Михея, сына Имлы».","10":"На площади у ворот Самарии сидели на тронах в полном царском облачении царь Израиля и Иосафат, царь Иудеи, а все пророки в исступлении пророчествовали перед ними.","11":"Седекия, сын Кенааны, приделал себе железные рога и возглашал: «Так говорит Господь: этими рогами ты забодаешь арамеев, изничтожишь их!»","12":"И все остальные пророки предрекали то же самое. «Иди на Рамот Галаадский! – говорили они. – Удача с тобой! Господь отдаст его в руки царя!»","13":"Посланец, которому велено было позвать Михея, сказал ему: «Все пророки в один голос сулят царю удачу. Хорошо бы и твое пророчество было таким же, как их пророчество. Хорошо бы и ты предрек удачу».","14":"Михей ответил: «Клянусь Господом, я скажу то, что мне откроет Господь».","15":"Михей пришел к царю, и царь спросил у него: «Михей, идти нам войною на Рамот Галаадский или нет?» – «Иди! – ответил Михей. – Удача с тобой! Господь отдаст его в руки царя!»","16":"Царь сказал: «Сколько же раз я буду тебя заклинать: говори мне правду и только правду, во имя Господа!»","17":"И тогда сказал Михей: «Я видел: все израильское войско по горам рассеяно, словно овцы без пастуха. И сказал Господь: у них нет хозяина, пусть расходятся без боя по домам». –","18":"«Говорил же я тебе, – сказал царь Израиля Иосафату, – он никогда не пророчит мне ничего хорошего, всегда одни беды».","19":"А Михей продолжал: «Выслушай слово Господа. Я видел Господа: Он восседал на престоле, и все небесное воинство стояло рядом с Ним, по правую и по левую руку от Него.","20":"Господь спросил: „Кто одурачит Ахава, чтобы он пошел в поход и пал в Рамоте Галаадcком?\" Каждый предлагал свое.","21":"Выступил вперед некий дух, предстал пред Господом и сказал: „Я его одурачу!\" Господь спросил: „Как?\"","22":"Тот ответил: „Я пойду и стану лживым духом в устах всех его пророков\". И Господь промолвил: „Да, тебе удастся одурачить его. Иди, делай, как сказал\".","23":"Так вот, смотри – в уста всех этих твоих пророков Господь вложил лживый дух. Господь вынес тебе приговор».","24":"Тогда Седекия, сын Кенааны, подошел, ударил Михея по щеке и сказал: «Это еще каким таким образом дух Господа меня покинул и стал говорить с тобой?»","25":"Михей ответил: «Придет день, узнаешь. И тогда забьешься в самый дальний угол дома, чтоб тебя не нашли». –","26":"«Возьмите Михея, – приказал царь Израиля, – отведите его к Амону, градоначальнику, и Иоасу, сыну царя,","27":"и передайте им: „Так говорит царь: бросьте его в темницу, и пусть сидит на хлебе и воде, пока я не вернусь с войны\"».","28":"Михей ответил: «Если ты вернешься с войны, то не Господь вещал через меня!» (И сказал Михей: «Внемлите мне, все народы…»)","29":"А царь Израиля и Иосафат, царь Иудеи, пошли войною на Рамот Галаадский.","30":"«Я надену чужую одежду и брошусь в бой, – сказал царь Израиля Иосафату, – а ты оставайся в своих царских одеждах». Царь Израиля надел чужую одежду и бросился в бой.","31":"А царь арамеев приказал начальникам своих колесничных отрядов (их у него было тридцать два): «Не вступайте в бой ни с командирами, ни с рядовыми – только с царем Израиля».","32":"Когда начальники арамейских колесничных отрядов увидели Иосафата, то решили, что это и есть царь Израиля, и повернули к нему, чтобы сразиться с ним. Иосафат закричал.","33":"Те увидели, что это не царь Израиля, и повернули в другую сторону.","34":"А какой-то лучник выстрелил – и, сам того не зная, сразил царя Израиля. Стрела прошла в щель между латами. «Поворачивай, вывози меня из боя! – сказал царь. – Я ранен».","35":"Сражение в тот день было жарким. Царя поддерживали, чтобы он стоял на колеснице, на виду у арамеев, но к вечеру он умер. Колесница была залита кровью из его раны.","36":"Когда зашло солнце, по войску пронесся клич: «Возвращаемся! Каждый – в свой город, в свою землю!»","37":"Мертвого царя отвезли в Самарию и там похоронили.","38":"Колесницу мыли в Самарийском пруду, и псы лизали кровь убитого, и тут же подмывались проститутки. Так исполнилось слово Господа.","39":"А прочее об Ахаве и его деяниях – о строительстве дворца из слоновой кости и обо всех отстроенных им городах – написано в «Летописях царей Израиля»!","40":"Ахав почил с предками; царем после него стал его сын Ахазия.","41":"Иосафат, сын Асы, стал царем Иудеи в четвертый год царствования Ахава, царя Израиля.","42":"Тридцати пяти лет от роду Иосафат стал царем и двадцать пять лет царствовал в Иерусалиме. Его мать – Азува, дочь Шилхи .","43":"Он во всем следовал за своим отцом Асой, и его дела были угодны Господу. Вот только капища оставались, и народ свои жертвы приносил, и закалывал, и сжигал в капищах.","44":"С царем Израиля у Иосафата был мир.","45":"А прочее об Иосафате, о его деяниях и доблести и о войнах, которые он вел, написано в «Летописях царей Иудеи».","46":"Иосафат уничтожил последних «посвященных», которые еще оставались при его отце Асе.","47":"Царя в это время в Эдоме не было – был царский наместник.","48":"Иосафат построил таршишские корабли и хотел снарядить их в Офир за золотом; но они так и не поплыли – разбились в Эцион – Гевере.","49":"(Ахазия, сын Ахава, предлагал тогда Иосафату: «Пусть мои люди поплывут с твоими на этих кораблях», – но Иосафат не согласился.)","50":"Иосафат почил с предками и был похоронен вместе с предками в Городе Давидовом. Царем после него стал его сын Иорам.","51":"Ахазия, сын Ахава, стал царем Израиля в семнадцатый год царствования Иосафата, царя Иудеи. Два года царствовал он в Самарии.","52":"Он творил дела, ненавистные Господу, шел по тому же пути, что отец и мать его, по пути Иеровоама, сына Невата, по вине которого весь Израиль погряз в грехе.","53":"Он служил Ваалу и поклонялся ему, оскорбляя Господа, Бога Израиля, – во всем поступал так же, как и его отец."}};
